#include <iostream>
#include <vector>
using namespace std;

int w, h;
int C[100][100];
bool R[100][100];

void dfs_visit(int h, int w, int y, int x){
    if(y < 0 || h <= y || x < 0 || w <= x || C[y][x] == 0){
        return;
    }

    if(R[y][x]){
        return;
    }

    R[y][x] = true;

    dfs_visit(h, w, y-1, x-1);
    dfs_visit(h, w, y-1, x);
    dfs_visit(h, w, y-1, x+1);
    dfs_visit(h, w, y, x-1);
    dfs_visit(h, w, y, x+1);
    dfs_visit(h, w, y+1, x-1);
    dfs_visit(h, w, y+1, x);
    dfs_visit(h, w, y+1, x+1);
}

int dfs(int h, int w){
    int cnt = 0;
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            if(C[i][j] == 1 && !R[i][j]){
                cnt++;
                dfs_visit(h, w, i, j);
            }
        }
    }

    return cnt;
}


int main(void){

    while(true){
        cin >> w >> h;
        if(w == 0 && h == 0) break;

        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++){
                C[i][j] = 0;
                R[i][j] = false;
                cin >> C[i][j];
            }
        }

        cout << dfs(h, w) << endl;
    }

    return 0;


}

