typedef long long ll;
bool search(int i, int j, vector<vector<int>>& c, vector<vector<bool>> &gone) {
	if (gone[i][j])return false;
	if (c[i][j] == 0)return false;
	gone[i][j] = true;
	for (int I = -1; I < 2; I++) {
		for (int J = -1; J < 2; J++) {
			if(i+I>=0&&j+J>=0&&i+I<c.size()&&j+J<c[0].size())
			search(i + I, j + J, c, gone);
		}
	}
	return true;
}
int main() {
	int w, h;
	while (true) {
		cin >> w >> h;
		if (w == 0 && h == 0) {
			return 0;
		}
		vector<vector<int>> c(h, vector<int>(w, 0));
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				cin >> c[i][j];
				//cout << c[i][j] << " ";
			}
			//cout << endl;
		}
		vector<vector<bool>> gone(h, vector<bool>(w, false));
		int ans=0;
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (search(i, j, c, gone)) {
					ans++;
				}
			}
		}
		cout << ans << endl;
	}
}

