using namespace std;
int field[50][50];
int w, h;

void dfs(int i, int j){
    field[i][j] = 0;
    for(int di=-1; di<=1; di++){
        for(int dj=-1; dj<=1; dj++){
            int ni = i+di;
            int nj = j+dj;
            if(field[ni][nj]==1 && 0 <= ni && ni < h &&
                    0 <= nj && nj < w){
                dfs(ni,nj);
            }
        }
    }
    return;
}

int main(){
    while(cin >> w >> h){
        if(w==0 && h==0) break;
        REP(i,h){
            REP(j,w){
                cin >> field[i][j];
            }
        }

        int cnt = 0;
        REP(i,h){
            REP(j,w){
                if(field[i][j] == 1){
                    dfs(i,j);
                    cnt++;
                }
            }
        }
        cout << cnt << endl;
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;

int main(){
    do{
        long long w, h;
        cin >> w >> h;
        if(w == 0)break;

        vector<vector<int>> c(h + 2, vector<int>(w + 2));
        for(int i = 0; i < h; ++i){
            for(int j = 0; j < w; ++j){
                cin >> c[i + 1][j + 1];
            }
        }

        queue<pair<int, int>> q;
        constexpr int move[9] = {0, 1, 1, -1, 0, -1, -1, 1};

        long long ans = 0;

        for(int i = 1; i <= h; ++i){
            for(int j = 1; j <= w; ++j){
                if(c[i][j]){
                    ++ans;

                    q.emplace(i, j);
                    c[i][j] = false;

                    while(!q.empty()){
                        auto t = q.front();
                        q.pop();
                        for(int i = 0; i < 8; ++i){
                            int y = t.first + move[i];
                            int x = t.second + move[i + 1];
                            if(c[y][x]){
                                q.emplace(y, x);
                                c[y][x] = false;
                            }
                        }
                    }

                }
            }
        }

        cout << ans << endl;

    }while(true);

    return 0;
}

