  unionfind(ll N){
    par.resize(N);
    for(ll i=0;i<N;i++)par[i]=i;
    treesize.resize(N);
    for(ll i=0;i<N;i++)treesize[i]=1;
  }
  ll root(ll x){
    ll r;
    if(par[x]==x)return x;
    r=root(par[x]);
    if(par[x]!=r){
      treesize[r]+=treesize[x];
      treesize[x]=0;
      par[x]=r;
    }
    return r;
  }
  void unite(ll x,ll y){
    ll px=root(x);
    ll py=root(y);
    if(px!=py){
      par[px]=py;
      treesize[py]+=treesize[px];
      treesize[px]=0;
    }
  }
  bool parcheck(ll x,ll y){
    ll px=root(x);
    ll py=root(y);
    return px==py;
  }
  ll size(ll x){
    ll px=root(x);
    return treesize[px];
  }
};

int main(){
  while(1){
  ll i,j=0,N,M,cnt=0;
  cin>>M>>N;
  if(N+M==0)return 0;
  unionfind tree(N*M);
  vec v(N*M);
  set<ll> se;
  rep(i,N){
    rep(j,M){
      cin>>v[i*M+j];
      if(v[i*M+j]==1){
        if(i>0&&v[(i-1)*M+j]==1){
          tree.unite(i*M+j,(i-1)*M+j);
        }
        if(j>0&&v[i*M+j-1]==1){
          tree.unite(i*M+j,i*M+j-1);
        }
        if(i>0&&j>0&&v[(i-1)*M+j-1]==1){
          tree.unite(i*M+j,(i-1)*M+j-1);
        }
        if(i>0&&j<M-1&&v[(i-1)*M+j+1]==1){
          tree.unite(i*M+j,(i-1)*M+j+1);
        }
      }else{
        cnt++;
      }
    }
  }

  rep(i,N*M){
    ll K=tree.root(i);
    se.insert(K);
  }
  cout<<(ll)se.size()-cnt<<endl;
  se.clear();
}}

