        int map[52][52] = { {0} };
        int check[52][52] = { {0} };

        int i, j;
        for(j=1; j<=h; j++){
            for(i=1; i<=w; i++){
                cin >> map[j][i];
            }
        }


        int label = 1;

        int x, y;
        for(y=1; y<=h; y++){
            for(x=1; x<=w; x++){
                if(map[y][x] == 1){
                    if(check[y][x-1] || check[y-1][x-1] || check[y-1][x] || check[y-1][x+1]){
                        int min;
                        if(check[y][x-1]){
                            min = check[y][x-1];
                        } else {
                            min = 2500;
                        }
                        for(int k=x-1; k<=x+1; k++){
                            if(check[y-1][k] != 0 && check[y-1][k] < min) min = check[y-1][k];
                        }
                        check[y][x] = min;
                    } else {
                        check[y][x] = label;
                        label++;
                    }
                }
            }
        }


        for(y=h; y>0; y--){
            for(x=w; x>0; x--){
                if(check[y][x]){
                    int min = check[y][x];
                    for(int n=y-1; n<=y+1; n++){
                        for(int k=x-1; k<=x+1; k++){
                            if(check[n][k] != 0 && check[n][k] < min) min = check[n][k];
                        }
                    }
                    check[y][x] = min;
                }
            }
        }

        int count = 0;

        for(y=1; y<=h; y++){
            for(x=1; x<=w; x++){
                if(count < check[y][x]) count = check[y][x];
            }
        }

        cout << count << endl;

    }


    return 0;
}

