#include<iostream>
using namespace std;

void exploreIsland( bool c[50][50], int h, int w, int y, int x )
{
    c[y][x] = 0;

    if( y - 1 >= 0 && c[y-1][x] == 1 )
        exploreIsland( c, h, w, y - 1, x ); 
    if( x - 1 >= 0 && y - 1 >= 0 && c[y-1][x-1] == 1 )
        exploreIsland( c, h, w, y - 1, x - 1 ); 
    if( x + 1 < w && y - 1 >= 0 && c[y-1][x+1] == 1 )
        exploreIsland( c, h, w, y - 1, x + 1 );
    if( x - 1 >= 0 && c[y][x-1] == 1 )
        exploreIsland( c, h, w, y, x - 1 ); 
    if( x + 1 < w && c[y][x+1] == 1 )
        exploreIsland( c, h, w, y, x + 1 );
    if( y + 1 < h && c[y+1][x] == 1 )
        exploreIsland( c, h, w, y + 1, x ); 
    if( x - 1 >= 0 && y + 1 < h && c[y+1][x-1] == 1 )
        exploreIsland( c, h, w, y + 1, x - 1 ); 
    if( x + 1 < w && y + 1 < h && c[y+1][x+1] == 1 )
        exploreIsland( c, h, w, y + 1, x + 1 ); 
}

int main()
{
    int h, w;
    bool c[50][50];

    while( cin >> w >> h )
    {
        if( h == 0 && w == 0 )
            break;

        for( int i = 0; i < h; i++ )
            for( int j = 0; j < w; j++ )
                cin >> c[i][j];

        int cnt = 0;
        for( int i = 0; i < h; i++ )
            for( int j = 0; j < w; j++ )
                if( c[i][j] == 1 )
                {
                    exploreIsland( c, h, w, i, j );
                    cnt++;
                }
        cout << cnt << endl;
    }
    return 0;
}

