typedef vector<vector<int>> vv;

int hashp(int i, int j){
    return i*100 + j;
}

void bfs(const vv& table, vv& is_visited, int si, int sj) {
    queue<int> q;
    q.push(hashp(si,sj));
    while(!q.empty()) {
        int hash_value = q.front();
        q.pop();
        int i = hash_value/100;
        int j = hash_value%100;

        if(i >= table.size() || i < 0 || j >= table[0].size() || j < 0)
            continue;
        if(!table[i][j])
            continue;
        if(is_visited[i][j])
            continue;
        is_visited[i][j] = 1;
        q.push(hashp(i+1,j));
        q.push(hashp(i-1,j));
        q.push(hashp(i,j+1));
        q.push(hashp(i,j-1));
        q.push(hashp(i+1,j+1));
        q.push(hashp(i+1,j-1));
        q.push(hashp(i-1,j+1));
        q.push(hashp(i-1,j-1));
        // cout << "pushed" << endl;
    }
    return;
}

int main(){
    int w,h;
    while(cin >> w >> h) {
        if (w == 0 && h ==0)
            break;
        vector<vector<int>> table;
        vector<vector<int>> is_visited;
        rep(i, h) {
            vector<int> tmp(w, 0);
            table.push_back(tmp);
            is_visited.push_back(tmp);
            rep(j, w) {
                cin >> table[i][j];
            }
        }
        int count = 0;
        rep(i, h) {
            rep(j, w) {
                if(table[i][j] == 1 && is_visited[i][j] == 0) {
                    count++;
                    bfs(table, is_visited, i, j);
                }
            }
        }
        cout << count << endl;
    }
}

