void mark(const int w, const int h, Graph<int> &map, int x, int y) {
    if (x < 0 || x >= w || y < 0 || y >= h) {
        return;
    }
    if (map[x][y] != 1) {
        return;
    }
    map[x][y] = 2;
    mark(w, h, map, x + 1, y - 1);
    mark(w, h, map, x, y - 1);
    mark(w, h, map, x - 1, y - 1);
    mark(w, h, map, x + 1, y);
    mark(w, h, map, x - 1, y);
    mark(w, h, map, x + 1, y + 1);
    mark(w, h, map, x, y + 1);
    mark(w, h, map, x - 1, y + 1);
}

