const int dx[] = { 0, 1, 0, -1, 1, -1, -1, 1 };
const int dy[] = { -1, 0, 1, 0, 1, 1, -1, -1 };

int W, H;

int dfs(vec2<int>& I, int x, int y) {
	if (I[y][x] == 0)return 0;
	I[y][x] = 0;
	REP(i, 8) {
		int nx = x + dx[i];
		int ny = y + dy[i];
		if (range2d(nx, ny, W, H)) {
			dfs(I, nx, ny);
		}
	}
	return 1;
