  while (cin >> w >> h) {
    if (w == 0 && h == 0) {
      break;
    }
    int count = 0;
    vector<vector<int>> c(h, vector<int>(w));
    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        cin >> c[i][j];
        if (c[i][j] == 0) {
          count++;
        }
      }
    }
    auto idx = [&](int i, int j) {
      return i*w + j;
    };
    auto outfield = [&](int i, int j) {
      return i < 0 || i >= h || j < 0 || j >= w;
    };
    UnionFind uf(w*h);
    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        for (int x = -1; x <= 1; x++) {
          for (int y = -1; y <= 1; y++) {
            if (outfield(i + x, j + y)) {
              continue;
            }
            if (c[i][j] == 1 && c[i + x][j + y] == 1) {
              uf.unionSet(idx(i, j), idx(i + x, j + y));
            }
          }
        }
      }
    }
    cout << uf.size() - count << endl;
  }
}

