			erase(island,x+m,y);
		}
		if(island[x][y+m]==1){
			erase(island,x,y+m);
		}
		if(island[x+m][y+m]==1){
			erase(island,x+m,y+m);
		}
		if(island[x-m][y+m]==1){
			erase(island,x-m,y+m);
		}
	}
}
