			f[i][j] = 0;
		}
		for(int i=0; i<h; ++i) for(int j=0; j<w; ++j) {
			mapst m = {j, i}, ms;
			if(func(j,i)) {
				q.push(m);
				ans++;
				do {
					m = q.front();
					q.pop();

					f[m.y][m.x] = 1;
					if(m.x>0&&m.y>0) if(func(m.x-1,m.y-1)) {
						ms.x = m.x-1; ms.y = m.y-1;
						q.push(ms);
					}
					if(m.y>0) if(func(m.x,m.y-1)) {
						ms.x = m.x; ms.y = m.y-1;
						q.push(ms);
					}
					if(m.x<w-1&&m.y>0) if(func(m.x+1,m.y-1)) {
						ms.x = m.x+1; ms.y = m.y-1;
						q.push(ms);
					}
					if(m.x<w-1) if(func(m.x+1,m.y)) {
						ms.x = m.x+1; ms.y = m.y;
						q.push(ms);
					}
					if(m.x<w-1&&m.y<h-1) if(func(m.x+1,m.y+1)) {
