						ms.x = m.x; ms.y = m.y+1;
						q.push(ms);
					}
					if(m.x>0&&m.y<h-1) if(func(m.x-1,m.y+1)) {
						ms.x = m.x-1; ms.y = m.y+1;
						q.push(ms);
					}
					if(m.x>0) if(func(m.x-1,m.y)) {
						ms.x = m.x-1; ms.y = m.y;
						q.push(ms);
					}
