void sink(int i, int j,int w,int h, int** field) {
	field[i][j] = 0;
	if (i > 0) {
		if (field[i - 1][j])sink(i - 1, j, w, h, field);
	}
	if (i < h-1) {
		if (field[i + 1][j])sink(i + 1, j, w, h, field);
	}
	if (j > 0) {
		if (field[i][j-1])sink(i , j-1, w, h, field);
	}
	if (j < w-1) {
		if (field[i][j+1])sink(i , j+1, w, h, field);
	}
	if (i > 0 && j > 0) {
		if (field[i - 1][j - 1])sink(i - 1, j - 1, w, h, field);
	}
	if (i > 0 && j < w - 1) {
		if (field[i - 1][j + 1])sink(i - 1, j + 1, w, h, field);
	}
	if (i < h-1 && j > 0) {
		if (field[i + 1][j - 1])sink(i + 1, j - 1, w, h, field);
	}
	if (i < h-1 && j < w-1) {
		if (field[i + 1][j + 1])sink(i + 1, j + 1, w, h, field);
	}
}

