void sink_one_island(int x, int y) {
  if (x < 0 or X < x or y < 0 or Y < y or !MAP[x][y])
    return;

  MAP[x][y] = false;
  for (int i = 0; i < 8; i++)
    sink_one_island(x + dx[i], y + dy[i]);
}

int sink_all_islands() {
  int islands = 0;

  for (int x = 0; x < X; x++) {
    for (int y = 0; y < Y; y++) {
      if (MAP[x][y]) {
        sink_one_island(x, y);
        islands++;
      }
    }
  }

  return islands;
}

