class UnionFind {
public:
    vector<i64> p;     // 親ノード。ただし根の場合 -(集合の要素数)
    i64         n_set; // 集合の個数

    explicit UnionFind(i64 n) : p(n, -1), n_set(n) {}

    i64 node_count() const { return SIZE(p); }

    // 集合の個数
    i64 set_count() const { return n_set; }

    // xが属する集合のサイズ
    i64 set_size(i64 x) { return -p[root(x)]; }

    bool is_root(i64 x) const { return p[x] < 0; }

    i64 root(i64 x) {
        return compress(x);
    }

    // x, y を併合する
    // 併合できた場合 true を返す(改造用。無改造の場合常に成功する)
    bool unite(i64 x, i64 y) {
        i64 rx = root(x);
        i64 ry = root(y);

        if(rx == ry) return false;

        // 要素数が大きい方を根とするため、必要ならswap処理
        if(set_size(rx) < set_size(ry)) {
            swap(rx, ry);
        }
        // rx を根とする
        p[rx] += p[ry]; // 要素数を加算
        p[ry]  = rx;    // rx を ry の親にする

        --n_set;

        return true;
    }

    // 同一集合に属するか
    bool same(i64 x, i64 y) {
        return root(x) == root(y);
    }

private:
    // 経路圧縮
    // xの根を返す
    i64 compress(i64 x) {
        if(is_root(x)) return x;

        i64 r = compress(p[x]);
        p[x] = r;
        return r;
    }
};

pair<i64,i64> idx2xy(i64 w, i64 i) {
    i64 x = i % w;
    i64 y = i / w;

    return PAIR(x,y);
}

i64 xy2idx(i64 w, i64 x, i64 y) {
    return w*y + x;
}

void solve(vector<vector<i64>> M) {
    i64 H = SIZE(M);
    i64 W = SIZE(M[0]);

    UnionFind uf(H*W);
    const auto chk_unite = [W, &M, &uf](i64 x1, i64 y1, i64 x2, i64 y2) {
        i64 i1 = xy2idx(W, x1, y1);
        i64 i2 = xy2idx(W, x2, y2);
        if(M[y1][x1] == M[y2][x2])
            uf.unite(i1, i2);
    };

    FOR(y, 1, H-1) FOR(x, 1, W-1) {
        chk_unite(x, y, x+1, y  );
        chk_unite(x, y, x-1, y+1);
        chk_unite(x, y, x  , y+1);
        chk_unite(x, y, x+1, y+1);
    }

    HashSet<i64> roots;
    FOR(y, 1, H-1) FOR(x, 1, W-1) {
        i64 r = uf.root(xy2idx(W, x, y));
        i64 rx,ry; tie(rx,ry) = idx2xy(W, r);
        if(M[ry][rx] == 1)
            roots.emplace(r);
    }

    PRINTLN(SIZE(roots));
}

signed main(signed /*argc*/, char** /*argv*/) {
    while(true) {
        i64 W, H; RD(W); RD(H);
        if(W == 0 && H == 0) break;

        W += 2; H += 2;
        vector<vector<i64>> M(H, vector<i64>(W, 0));
        FOR(y, 1, H-1) FOR(x, 1, W-1) {
            RD(M[y][x]);
        }

        solve(move(M));
    }

    EXIT();
}

