void Delete(int sx,int sy,int h,int w){
  queue<int>que;
  que.push(sx);que.push(sy);
  while(que.size()){
    int x=que.front();que.pop();
    int y=que.front();que.pop();
    for(int i=0;i<8;i++){
      if(d[y+dy[i]][x+dx[i]]==1&&0<=y+dy[i]&&y+dy[i]<h&&0<=x+dx[i]&&x+dx[i]<w){
	d[y+dy[i]][x+dx[i]]=0;
	que.push(x+dx[i]);
	que.push(y+dy[i]);
      }
    }
  }
}

