struct Solver {
  Solver(int w, int h) : w(w), h(h) { memset(field, 0, sizeof(field)); }
  void input(){
    for (int y = 0; y < h; y++){
      for (int x = 0; x < w; x++){
        field[y][x] = in();
      }
    }
  }
  int solve(){
    int count = 0;
    for (int y = 0; y < h; y++){
      for (int x = 0; x < w; x++){
        if (field[y][x]){
          count++;
          erase(x, y);
        }
      }
    }
    return count;
  }

  void erase(int x, int y){
    if (invalid(x, y)) return;
    if (!field[y][x]) return;
    field[y][x] = 0;
    for (int d = 0; d < 8; d++){
      erase(x + dx[d], y + dy[d]);
    }
  }
  bool invalid(int x, int y){
    return x < 0 || w <= x || y < 0 || h <= y;
  }
  const int w, h;
  int field[64][64];
};

