		board[y][x] == 0 )
	{
		return 0;
	}

	board[y][x] = 0;

	for ( int i = -1; i <= 1; i++ )
	{
		for ( int j = -1; j <= 1; j++ )
		{
			dfs( board, h, w, y + i, x + j );
		}
	}
	return 1;
}

