struct Union_Find {
	vector<int> parent; //親
	vector<int> num; //根としたときの木サイズ

	Union_Find(int N) : parent(N),num(N,1) {
		for(int i=0; i<N; i++) {
			parent[i]=i;
		}
	}

	int root(int x) {
		if(parent[x]==x) return x;
		return parent[x]=root(parent[x]);
	}

	void merge(int x, int y) {
		int xrt=root(x);
		int yrt=root(y);
		if(xrt==yrt) return;
		parent[xrt]=yrt;
		num[yrt]+=num[xrt];
	}

	bool same(int x, int y) {
		return root(x)==root(y);
	}

	int size(int x) {
		return num[root(x)];
	}
};

struct Ford_Fulkerson {
	struct _edge {
		int next;
		int rev; // 逆辺の_edgeがG[next][rev]に存在する
		ll cap;
	};

	vector<vector<_edge>> G;
	vector<bool> used;

	Ford_Fulkerson(int N) : G(N),used(N) {}

	void add_edge(int from, int to, ll cap) {
		G[from].push_back((_edge){to,(int)G[to].size(),cap});
		G[to].push_back((_edge){from,(int)G[from].size()-1,0});
	}

	ll f_dfs(int s, int t, ll flow) {
		if(s==t) return flow;
		used[s]=true;
		for(_edge &ed : G[s]) {
			if(!used[ed.next] && ed.cap>0) {
				ll captmp=f_dfs(ed.next,t,min(flow,ed.cap));
				if(captmp>0) {
					ed.cap-=captmp;
					G[ed.next][ed.rev].cap+=captmp;
					return captmp;
				}
			}
		}
		return 0LL;
	}

	ll max_flow(int s, int t) {
		ll res=0LL;
		while(1) { // 最大になるまで繰り返し
			used.assign(used.size(),false);
			ll restmp=f_dfs(s,t,LLINF);
			if(restmp==0) return res;
			res+=restmp;
		}
	}
};


