void dfs(long long y,long long x,vector<vector<bool>> &seen,vector<vector<long long>> grid){
	vector<long long> dy={1,1,1,0,0,-1,-1,-1};
	vector<long long> dx={1,0,-1,1,-1,1,0,-1};

	for(long long i=0;i<8;i++){
		long long py=y+dy.at(i);
		long long px=x+dx.at(i);

		if(py<0 || py>=h || px<0 || px>=w || grid.at(py).at(px)==0 || seen.at(py).at(px)) continue;

		seen.at(py).at(px)=true;
		dfs(py,px,seen,grid);
	}
}

int main(){
	cin>>w>>h;

	while(h!=0 || w!=0){
		vector<vector<long long>> grid(h,vector<long long>(w));
