				cin>>grid.at(i).at(j);
			}
		}

		vector<vector<bool>> seen(h,vector<bool>(w,false));
		long long ans=0;

		for(long long i=0;i<h;i++){
			for(long long j=0;j<w;j++){
				if(grid.at(i).at(j)==0 || seen.at(i).at(j)) continue;
				ans++;
				seen.at(i).at(j)=true;
				dfs(i,j,seen,grid);
			}
		}

		cout<<ans<<endl;
		cin>>w>>h;
	}

	return 0;
