    maze[x][y] = false;
    while(q.size() > 0){
        int nx = q.front().first;
        int ny = q.front().second;
        q.pop();
        for (int i = -1; i <= 1; i++){
            for (int j = -1; j <= 1; j++){
                if (0 <= nx+i && nx+i < h && 0 <= ny+j && ny+j < w && maze[nx+i][ny+j]){
                    maze[nx+i][ny+j] = false;
                    q.push({nx+i, ny+j});
                }
            }
        }
    }
}

