int grid[50][50];
bool used[50][50];
int move_h[8] = {-1, 1, 0, 0, -1, 1, -1, 1};
int move_w[8] = {0, 0, -1, 1, 1, -1, -1, 1};

void dfs(int cur_h, int cur_w, int h, int w){
  used[cur_h][cur_w] = true;
  for(int i = 0; i < 8; i++){
    int next_h = cur_h + move_h[i];
    int next_w = cur_w + move_w[i];

    if(0 <= next_h && next_h < h && 0 <= next_w && next_w < w 
        && !used[next_h][next_w] && grid[next_h][next_w] == 1){
      dfs(next_h, next_w, h, w);
    }
  }
}
int main(){
  while(true){
