      for(int j = 0; j < w; j++){
        cin >> grid[i][j];
        used[i][j] = false;
      }
    }

    int ans = 0;
    for(int i = 0; i < h; i++){
      for(int j = 0; j < w; j++){
        if(!used[i][j] && grid[i][j] == 1){
          ans ++;
          dfs(i, j, h, w);
        }
      }
    }
    cout << ans << endl;
  }
  return 0;
}

