                cnt++;
                to_visit.push(make_pair(i, j));
                seen[i][j] = true;
                while (to_visit.empty() == false) {
                    pair<int, int> cur_pos = to_visit.top(); to_visit.pop();
                    int cur_h = cur_pos.first;
