void land_dfs(int x, int y, int n) {


	c[x][y] = n;

	// 島の発見中
	// 周囲8マスに島チェック

	for (int yy = -1; yy <= 1; yy++) {
		for (int xx = -1; xx <= 1; xx++) {
			if (x + xx < 0 || x + xx >(w - 1)) continue;
			if (y + yy < 0 || y + yy >(h - 1)) continue;
			if (c[x + xx][y + yy] != 1) continue;

