typedef char Graph[501][501];
Graph graph;
bool seen[501][501];

void dfs(const Graph& G, int v, int w) {
	// そのセルに対する処理
	seen[v][w] = true;

	// そのセルからつながるセルに処理を移行
	if (v + 1 < h_size) {
		if (!seen[v + 1][w] && G[v + 1][w] == '1') {
			//[v+1][w]に対する処理
			dfs(G, v + 1, w);
		}
		if (w + 1 < w_size) {
			if (!seen[v + 1][w + 1] && G[v + 1][w + 1] == '1') {
				//[v+1][w+1]に対する処理
				dfs(G, v + 1, w + 1);
			}
		}
		if (w - 1 >= 0) {
			if (!seen[v + 1][w - 1] && G[v + 1][w - 1] == '1') {
				//[v+1][w-1]に対する処理
				dfs(G, v + 1, w - 1);
			}
		}
	}
	if (v - 1 >= 0) {
		if (!seen[v - 1][w] && G[v - 1][w] == '1') {
			//[v-1][w]に対する処理
			dfs(G, v - 1, w);
		}

		if (w + 1 < w_size) {
			if (!seen[v - 1][w + 1] && G[v - 1][w + 1] == '1') {
				//[v-1][w+1]に対する処理
				dfs(G, v - 1, w + 1);
			}
		}
		if (w - 1 >= 0) {
			if (!seen[v - 1][w - 1] && G[v - 1][w - 1] == '1') {
				//[v-1][w-1]に対する処理
				dfs(G, v - 1, w - 1);
			}
		}
	}
	if (w + 1 < w_size) {
		if (!seen[v][w + 1] && G[v][w + 1] == '1') {
			//[v][w+1]に対する処理
			dfs(G, v, w + 1);
		}
	}
	if (w - 1 >= 0) {
		if (!seen[v][w - 1] && G[v][w - 1] == '1') {
			//[v][w-1]に対する処理
			dfs(G, v, w - 1);
		}
	}
}

