		for(int j=0; j<52; j++)
			field[i][j] = 0;
}

bool walk(int x, int y){
	if(field[y][x] == 0)
		return false;

	field[y][x] = 0;

	for(int i=-1; i<=1; i++)
		for(int j=-1; j<=1; j++)
