    UF(int n) : n(n), m(n), d(n, -1), r(n, 0){};
    int root(int i) {
        if(d[i] < 0) return i;
        return d[i] = root(d[i]);
    }
    bool same(int x, int y) { return root(x) == root(y); }
    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if(x == y) return false;

        if(r[x] < r[y])
            swap(x, y);
        else if(r[x] == r[y])
            r[x]++;
        d[x] += d[y];
        d[y] = x;
        --m;
        return true;
    }
    int size(int i) { return -d[root(i)]; }
    int size() { return m; }
};

int main() {
    int w, h;
    while(cin >> w >> h) {
        if(w == 0 && h == 0) break;
        vector<vi> d(h, vi(w));
        rep(i, h) rep(j, w) cin >> d[i][j];
        UF uf(h * w);
        rep(i, h) rep(j, w) {
            if(d[i][j]) REP(dy, -1, 2) REP(dx, -1, 2) {
                int x = j + dx, y = i + dy;
                if(min(x, y) < 0 || x >= w || y >= h || d[y][x] == 0)
                    continue;
                uf.unite(i * w + j, y * w + x);
            }
        }
        int ans = 0;
        rep(i, h) rep(j, w) if(d[i][j] && uf.root(i * w + j) == i * w + j) {
            ++ans;
            // cout << " " << i << " " << j << endl;
        }
        cout << ans << endl;
    }
    return 0;
}

