//cout << fixed << setprecision(10);

int field[100][100];
ll w, h;


void dfs(ll y, ll x){
    field[y][x] = 0;
    rep(i, 8){
        ll ny = y + ddy[i], nx = x + ddx[i];
        if(0 <= ny && ny < h && 0 <= nx && nx < w && field[ny][nx]){
            dfs(ny, nx);
        }
    }
}


int main(){
    vector<ll> res;
    while(1){
        cin >> w >> h;
        if(!w && !h) break;
        rep(hi, h){
            rep(wi, w){
                cin >> field[hi][wi];
            }
        }

        ll ans = 0;
        rep(hi, h){
            rep(wi, w){
                if(field[hi][wi]){
                    dfs(hi, wi);
                    ans++;
                }
            }
        }

        // cout << ans << endl;
        res.push_back(ans);
    }

    rep(i, res.size()) cout << res[i] << endl;
return 0;
}

