#include<map>
#define h first
#define w second
using namespace std;
typedef pair<int, int> P;

const int MAX_H = 55;
const int MAX_W = 55;

int grid[MAX_H][MAX_W];
bool is_checked[MAX_H][MAX_W];

void solve(int W, int H) {
    map<P, bool> is_exist;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> grid[i][j];
            is_checked[i][j] = false;
            is_exist[P(i, j)] = true;
        }
    }
    queue<P> Q;
    int land_cnt = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 1 && !is_checked[i][j]) {
                Q.push(P(i, j));
                is_checked[i][j] = true;
                while (!Q.empty()) {
                    P now_pos = Q.front();
                    Q.pop();
                    for (int k = -1; k <= 1; k++) {
                        for (int l = -1; l <= 1; l++) {
                            P new_pos = P(now_pos.h + k, now_pos.w + l);
                            if (!is_exist[new_pos]) continue;
                            if (is_checked[new_pos.h][new_pos.w]) continue;
                            if (grid[new_pos.h][new_pos.w] == 0) continue;
                            Q.push(new_pos);
                            is_checked[new_pos.h][new_pos.w] = true;
                        }
                    }
                }
                land_cnt++;
            }
        }
    }
    cout << land_cnt << endl;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int W, H;
    while (true) {
        cin >> W >> H;
        if (W == 0 && H == 0) break;
        solve(W, H);
    }
    return 0;
}

