int w,h;
int field[51][51];

// 現在地(x,y)
void dfs(int x, int y){
    // 今いるところを-1に置き換える
    field[y][x] = -1;

    // 移動する8方向をループ
    for(int dx = -1 ; dx <= 1 ; dx++ ){
        for(int dy = -1 ; dy <= 1 ; dy++ ){
            // x方向にdx, y方向にdy, 移動した場所を(mx,my)とする
            int mx = x + dx;
            int my = y + dy;
            // 範囲外に出たときは次の処理へ
            if( mx < 0 || my < 0 || mx >= w || my >= h ) continue;
            // 陸地だったら再帰呼び出し
            if( field[my][mx] == 1 ){
                dfs( mx , my );
            }
        }
    }
}

int main(){
    while( cin >> w >> h , w||h ){
        for(int y=0 ; y < h ; y++ ){
            for(int x=0 ; x < w ; x++ ){
                cin >> field[y][x];
            }
        }

        int ans = 0;
        for(int y=0 ; y < h ; y++ ){
            for(int x=0 ; x < w ; x++ ){
                if( field[y][x] == 1 ){ // 陸地があったら再帰関数を呼び出す
                    dfs( x , y );
                    ans++;
                }
            }
        }
        cout << ans << endl;
    }
}

