void land(int x,int y){
	stack<pair<int,int> > field2;
	int dx[]={1,1,1,-1,-1,-1,0,0},dy[]={1,0,-1,1,0,-1,1,-1};
	int xx,yy,flag,stka=1;

	field2.push(pair<int,int>(x,y));
	field[x][y]=0;

	while(1){
		flag=0;
		for(int i=0;i<9;i++){
			if(field2.top().first+dx[i]>=0&&field2.top().first+dx[i]<=w&&field2.top().second+dy[i]>=0&&field2.top().second+dy[i]<=h){
				if(field[field2.top().first+dx[i]][field2.top().second+dy[i]]==1){
					xx=field2.top().first+dx[i],yy=field2.top().second+dy[i];
					field[field2.top().first+dx[i]][field2.top().second+dy[i]]=0;
					field2.push(pair<int,int>(xx,yy));
					stka+=1;
					flag=1;
					break;
				}
			}
		}
		if(flag==0){
			field2.pop();
			stka--;
			if(stka==0){
				break;
			}
		}
	}
	return;
}

