class Solver {
public:
	static void solve() {
		int w, h;
		cin >> w >> h;
		vector<int> res;
		while (w > 0 && h > 0) {
			vector<vector<bool>> grid(h, vector<bool>(w));
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					int now;
					cin >> now;
					grid[i][j] = now;
				}
			}

			int cnt = 0;
			vector<vector<int>> visited(h, vector<int>(w, false));

			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					if (!grid[i][j] || visited[i][j])continue;

					cnt++;

					queue<tuple<int, int>> que;
					que.push(make_tuple(i, j));
					while (!que.empty()) {
						auto pos = que.front();
						que.pop();
						int y = get<0>(pos);
						int x = get<1>(pos);
						if (y < 0 || h <= y || x < 0 || w <= x
							|| !grid[y][x] || visited[y][x])continue;

						visited[y][x] = true;

						que.push(make_tuple(y - 1, x));
						que.push(make_tuple(y + 1, x));
						que.push(make_tuple(y, x - 1));
						que.push(make_tuple(y, x + 1));
						que.push(make_tuple(y - 1, x - 1));
						que.push(make_tuple(y + 1, x - 1));
						que.push(make_tuple(y - 1, x + 1));
						que.push(make_tuple(y + 1, x + 1));
					}
				}
			}

			res.emplace_back(cnt);

			cin >> w >> h;
		}

		for (int i = 0; i < res.size(); i++) {
			cout << res[i] << endl;
		}
	}
};

