void add_label(map<int,int> &tbl, int a, int b){
	if( a == b ) return;
	if(a < b){
		int tmp = a;
		a = b;
		b = tmp;
	}
	if( tbl.find(a) == tbl.end() ) {
		tbl[a] = b;
	} else {
		int bb = tbl.find(a)->second;
		if( b == bb ) return;
		if( bb > b ) {
			tbl[a] = b;
			tbl[bb] = b;
		} else {
			tbl[b] = bb;
		}
