void add_one(queue<pair<int, int>>& dst, int c_h, int c_w, int h, int w)
{
	if (c_h < 0 || h <= c_h || c_w < 0 || w <= c_w) return;

	dst.push(make_pair(c_h, c_w));
}

void solve_one(vector<vector<bool>>& map, int h, int w, int s_h, int s_w)
{
	queue<pair<int,int>> checks;
	checks.push(make_pair(s_h, s_w));

	while (!checks.empty()) {
		auto cur = checks.front();
		checks.pop();

		if (!map[cur.first][cur.second]) continue;

		map[cur.first][cur.second] = false;

		add_one(checks, cur.first + 1, cur.second    , h, w);
		add_one(checks, cur.first - 1, cur.second    , h, w);
		add_one(checks, cur.first    , cur.second + 1, h, w);
		add_one(checks, cur.first    , cur.second - 1, h, w);
		add_one(checks, cur.first + 1, cur.second + 1, h, w);
		add_one(checks, cur.first + 1, cur.second - 1, h, w);
		add_one(checks, cur.first - 1, cur.second + 1, h, w);
		add_one(checks, cur.first - 1, cur.second - 1, h, w);
	}
}

int solve(vector<vector<bool>>& map, int h, int w)
{
	int count = 0;

	int s_h = 0;
	int s_w = 0;

	while (s_h < h && s_w < w) {
		if (map[s_h][s_w]) {
			solve_one(map, h, w, s_h, s_w);
			count++;
		}

		s_w++;
		if (s_w == w) {
			s_h++;
			s_w = 0;
		}
	}

	return count;
}

int main()
{
	while (true) {
		int h, w; cin >> w >> h;
		if (h == 0 && w == 0) return 0;

		vector<vector<bool>> map(h, vector<bool>(w));
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				int s; cin >> s;
				if (s == 0) map[i][j] = false;
				if (s == 1) map[i][j] = true;
			}
		}

		int count = solve(map, h, w);
		cout << count << endl;
	}

	return 0;
}

