int dx[] = {0, 0, 1, -1, 1, -1, 1, -1}, dy[] = {1, -1, 0, 0, 1, -1, -1, 1}, W, H;
bool mem[50][50];

int bfs(int sx, int sy)
{
  if(!mem[sy][sx])
    return 0;
  queue<int> q;
  q.push(sx);
  q.push(sy);
  while(!q.empty())
  {
    int x = q.front(); q.pop();
    int y = q.front(); q.pop();
    mem[y][x] = 0;
    for(int i = 0; i < 8; i++)
    {
      int tx = x + dx[i];
      int ty = y + dy[i];
      if(tx >= 0 && tx < W && ty >= 0 && ty < H && mem[ty][tx])
      {
        q.push(tx);
        q.push(ty);
      }
    }
  }
  return 1;
}

