    field[h][w] = 0;

    for(int dh = -1; dh <= 1; dh++)
    {
        for(int dw = -1; dw <= 1; dw++)
        {
            int nh = h + dh;
            int nw = w + dw;

            if((nh >= H)||(nh < 0)||(nw >= W)||(nw < 0)) continue;
            if(field[nh][nw] == 0) continue;

            dfs(nh,nw);
        }
    }
}



