template<typename T>
array<pair<T,T>,8> neighbor8(const T& x, const T& y) {
    return array<pair<T,T>,8> {{
        { x-1, y-1 }, { x, y-1 }, { x+1, y-1 },
        { x-1, y   },             { x+1, y   },
        { x-1, y+1 }, { x, y+1 }, { x+1, y+1 },
    }};
}

template<typename T>
bool in_bounds(const T& x, const T& minx, const T& maxx) {
    return !(x < minx) && !(maxx < x);
}

template<typename T>
bool in_bounds_2(
    const T& x,    const T& y,
    const T& minx, const T& miny,
    const T& maxx, const T& maxy) {
    return in_bounds(x, minx, maxx) && in_bounds(y, miny, maxy);
}

template<typename T>
bool in_bounds_wh(const T& x, const T& y, const T& w, const T& h) {
    return in_bounds_2(x, y, T(0), T(0), w-1, h-1);
}

void dfs(vector<vector<i64>>& M, i64 sx, i64 sy) {
    i64 H = SIZE(M);
    i64 W = SIZE(M[0]);

    RECURSIVE([&](auto&& self, i64 x, i64 y) -> void {
        M[y][x] = 0;

        for(const auto& p : neighbor8(x,y)) {
            i64 xx,yy; tie(xx,yy) = p;
            if(!in_bounds_wh(xx, yy, W, H)) continue;
            if(M[yy][xx] == 1) self(xx,yy);
        }
    })(sx, sy);
}

void solve(vector<vector<i64>> M) {
    i64 H = SIZE(M);
    i64 W = SIZE(M[0]);

    i64 ans = 0;
    REP(y, H) REP(x, W) {
        if(M[y][x] == 1) {
            dfs(M, x, y);
            ++ans;
        }
    }

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/) {
    while(true) {
        i64 W, H; RD(W); RD(H);
        if(W == 0 && H == 0) break;

        vector<vector<i64>> M(H, vector<i64>(W));
        REP(y, H) REP(x, W) {
            RD(M[y][x]);
        }

        solve(move(M));
    }

    EXIT();
}

