void dfs(vector<vector<int> >& map, int y, int x, int H, int W, int index)
{
  int dx[8] = {-1, 0, 1, -1, 1, -1, 0, 1};
  int dy[8] = {-1, -1, -1, 0, 0, 1, 1, 1};

  map[y][x] = index;
  for (int i = 0; i < 8; i++)
  {
    if (y + dy[i] >= 0 && y + dy[i] < H && x + dx[i] >= 0 && x + dx[i] < W){
      if (map[y + dy[i]][x + dx[i]] == 1)
      {
        dfs(map, y + dy[i], x + dx[i], H, W, index);
      }
    }
  }
}

