	void dfs(int now, vector<vector<int>>& path, vector<int>& visit, int& time) {
		visit[now] = time;
		REP(i, path[now].size()) {
			int t = path[now][i];
			if (visit[t] < 0) {
				dfs(t, path, visit, time);
			}
		}
	}

	void solve() {
		IOS;
		int h, w;
		cin >> w >> h;
		while (h + w > 0) {
			vector<vector<int>> c(h, vector<int>(w));
			vector<vector<int>> path(h * w);
			REP(i, h) {
				REP(j, w) {
					cin >> c[i][j];
				}
			}
			int dy[] = { 0,1,1,1,0,-1,-1,-1 };
			int dx[] = { 1,1,0,-1,-1,-1,0,1 };
			REP(i, h) {
				REP(j, w) {
					if (c[i][j] == 1) {
						REP(k, 8) {
							int ny = i + dy[k];
							int nx = j + dx[k];
							if (0 <= ny && ny < h && 0 <= nx && nx < w) {
								if (c[ny][nx] == 1) {
									int next = ny * w + nx;
									int now = i * w + j;
									path[next].push_back(now);
									path[now].push_back(next);
								}
							}
						}
					}
				}
			}
			vector<int> visit(h * w, -1);
			int cnt = 0;
			REP(i, h) {
				REP(j, w) {
					int t = i * w + j;
					if (c[i][j]==1&&visit[t] < 0) {
						dfs(t, path, visit, cnt);
						cnt++;
					}
				}
			}
			put(cnt);
			cin >> w >> h;
		}
	}
} // namespace idaten

int main() {
	idaten::solve();
	return 0;
}

