using namespace std;

pair<int, int> serch_land(vector<vector<int> >& maps){
  for(int i = 0; i < maps.size(); i++){
    for(int j = 0; j < maps[i].size(); j++){
      if(maps[i][j] == 1){
        return make_pair(i, j);
      }
    }
  }
  return make_pair(-1, -1);
}

void delete_land(vector<vector<int> >& maps, pair<int, int> start){
  int dh[8] = {1, 1, 1, 0, 0, -1, -1, -1};
  int dw[8] = {1, 0, -1, 1, -1, 1, -1, 0};

  stack< pair<int, int> > s;
  s.push(start);
  pair<int, int> cur;
  maps[start.first][start.second] = 0;

  while(!s.empty()){
    cur = s.top();
    s.pop();

    for(int i = 0; i < 8; i++){
      if(maps[cur.first + dh[i]][cur.second + dw[i]] == 1){
        maps[cur.first + dh[i]][cur.second + dw[i]] = 0;
        pair<int, int> next = make_pair(cur.first + dh[i], cur.second + dw[i]);
        s.push(next);
      }
    }
  }
}

int main(){
  int w, h;

  while(cin >> w >> h, !(w == 0 && h == 0)){
    vector<vector<int> > maps = vector<vector<int> >(h+2, vector<int>(w+2));
    pair<int, int> land;

    for(int i = 0; i < h+2; i++){
      for(int j = 0; j < w+2; j++){
        if(i == 0 || j == 0 || i == h+1 || j == w+1){
          maps[i][j] = 0;
        }else{
          cin >> maps[i][j];
        }
      }
    }


    int cnt = 0;
    while(land = serch_land(maps), land.first != -1){
      cnt++;
      delete_land(maps, land);
    }
    cout << cnt << endl;

  }
}

