void dfs(vector<vector<bool>>& visited, int h, int w){
    if(visited[h][w]) return;
    visited[h][w]=true;
    int dx[3]={-1, 0, 1};
    int dy[3]={-1, 0, 1};
    for(int yi=0; yi<3; ++yi){
        for(int xi=0; xi<3; ++xi){
            if(field[h+dy[yi]][w+dx[xi]]) dfs(visited, h+dy[yi], w+dx[xi]);
        }
    }
}

