    for(int h=1; h<=H; ++h){
        for(int w=1; w<=W; ++w){
            if(!field[h][w]) continue;
            if(visited[h][w]) continue;
            dfs(visited, h, w);
            ++ans;
        }
    }
    return ans;
}

