struct UnionFind{
    vector<int> data;

    UnionFind(int N) : data(vector<int>(N,-1)){}

    int root(int x){
        if(data[x] < 0){
            return x;
        }else{
            return data[x] = root(data[x]);
        }
    }

    bool same(int x,int y){
        return root(x) == root(y);
    }

    void unite(int x,int y){
        if(!same(x,y)){
            x = root(x);
            y = root(y);
            if(data[x] < data[y]){
                data[x] += data[y];
                data[y] = x;
            }else{
                data[y] += data[x];
                data[x] = y;
            }
        }
        return;
    }

};

const int dx[] = {1,1,0,-1,-1,-1,0,1};
const int dy[] = {0,1,1,1,0,-1,-1,-1};

void solve(int w,int h){
    swap(w,h);
    int c[w][h];
    for(int i = 0;i < w;i++){
        for(int j = 0;j < h;j++){
            cin >> c[i][j];
        }
    }
    UnionFind uf(w*h);
    for(int i = 0;i < w;i++){
        for(int j = 0;j < h;j++){
            for(int k = 0;k < 8;k++){
                int x = i + dx[k];
                int y = j + dy[k];
                if(0 <= x && x < w && 0 <= y && y < h){
                    if(c[i][j] && c[x][y]){
                        uf.unite(i*h+j,x*h+y);
                    }
                }
            }
        }
    }
    set<int> s;
    for(int i = 0;i < w*h;i++)s.insert(uf.root(i));
    int ans = 0;
    for(auto x:s){
        ans += c[x/h][x%h];
    }
    cout << ans << endl;
}

int main(){
    int w,h;
    while(true){
        cin >> w >> h;
        if(!w && !h)return 0;
        solve(w,h);
    }
}

