class UnionFind{
public:
	vector<int> par;
	//0-indexed
	void init(int n = 1) {
		par.resize(n);
		for (int i = 0; i < n; ++i) par[i] = i;
	}
	int root(int x = 1){
		if(par[x]==x)return x;
		else{
			return par[x] = root(par[x]);
		}
	}
	void unite(int x = 1,int y = 1){
		x = root(x);
		y = root(y);
		if(x==y)return;
		par[x] = y;
	}
};

bool solve(){
	ll H,W;
	cin >> W >> H;
	UnionFind island;
	island.init(W*H);
	ll dx[] = {0,1,0,-1,1,1,-1,-1};
	ll dy[] = {1,0,-1,0,1,-1,1,-1};
 	if(H==0&&W==0)return false;
	ll tile[H][W];
	ll zero = 0;
	FOR(i,0,H)FOR(j,0,W)cin>>tile[i][j];
	FOR(i,0,H)FOR(j,0,W){
		if(tile[i][j]==1){
			ll x = i;
			ll y = j;
			FOR(k,0,8)if(x+dx[k]<H&&x+dx[k]>=0&&y+dy[k]<W&&y+dy[k]>=0){
				ll nx = x+dx[k];
				ll ny = y+dy[k];
				if(tile[nx][ny]==1)
					island.unite(x*W+y,nx*W+ny);
			}
		}else{
			zero++;
		}
	}
	set<ll> s;
	FOR(i,0,H*W)s.insert(island.root(i));
	cout << s.size() - zero << endl;
	return true;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	while(solve());
}

