    c[i][j]--;
    if(c[i+1][j-1])
        er(i+1,j-1);
    else if(c[i][j+1])
        er(i,j+1);
    else if(c[i+1][j])
        er(i+1,j);
    else if(c[i+1][j+1])
        er(i+1,j+1);
    else if(c[i-1][j+1])
        er(i-1,j+1);
    else if(c[i-1][j])
        er(i-1,j);
    else if(c[i-1][j-1])
        er(i-1,j-1);
    else if(c[i][j-1])
