#include <stdio.h>

using namespace std;

#define NUM 50

int w, h;
int c[NUM][NUM];
bool visited[NUM][NUM];
queue<pair<int, int> > Q;

void init(){
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            visited[i][j] = false;
        }
    }
}

bool can_visit(int i, int j){
    if(i < 0 || h <= i || j < 0 || w <= j){
        return false;
    }
    if(visited[i][j] || c[i][j] == 0){
        return false;
    }
    return true;
}

pair<int, int> find_new_place(){
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            if(can_visit(i, j)){
                return make_pair(i, j);
            }
        }
    }

    return make_pair(-1, -1);
}

bool exec(void){
    scanf("%d %d", &w, &h);
    if(w == 0 && h == 0){
        return false;
    }

    init();

    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            scanf("%d", &c[i][j]);
        }
    }

    int count = 0;

    while(true){
        pair<int, int> new_place = find_new_place();
        if(new_place.first == -1){
            break;
        }

        count++;

        Q.push(new_place);
        visited[new_place.first][new_place.second] = true;
        while(!Q.empty()){
            pair<int, int> p = Q.front(); Q.pop();
            int x = p.first;
            int y = p.second;

            vector<pair<int, int> > v;
            v.push_back(make_pair(x, y + 1));
            v.push_back(make_pair(x, y - 1));
            v.push_back(make_pair(x + 1, y + 1));
            v.push_back(make_pair(x + 1, y));
            v.push_back(make_pair(x + 1, y - 1));
            v.push_back(make_pair(x - 1, y + 1));
            v.push_back(make_pair(x - 1, y));
            v.push_back(make_pair(x - 1, y - 1));

            for(auto&& item : v){
                int x_ = item.first;
                int y_ = item.second;
                if(can_visit(x_, y_)){
                    visited[x_][y_] = true;
                    Q.push(make_pair(x_, y_));
                }
            }
        }
    }

    printf("%d\n", count);

    return true;
}

int main(void){
    while(exec()){
        ;
    }

    return 0;
}

