void dfs(int y, int x, int h, int w) {
    g_visited[y][x] = true;
    for (int i = 0; i < 8; i++) {
        int ny = y + dy[i], nx = x + dx[i];
        if (ny < 0 || ny >= h || nx < 0 || nx >= w) {
