using namespace std;
#define repeat(i,n) for (int i = 0; (i) <(int) (n); ++(i))
#define repeat_from(i,m,n) for (int i = (m); (i) <(int) (n); ++(i))
void dfs(int x, int y, int n, vector<vector<int> > & k, vector<vector<bool> > const & c) {
    int h = c.size();
    int w = c.front().size();
    if (x < 0 or w <= x or y < 0 or h <= y) return;
    if (k[y][x] or not c[y][x]) return;
    k[y][x] = n;
    repeat_from (dy,-1,1+1) {
        repeat_from (dx,-1,1+1) {
            dfs(x+dx,y+dy,n,k,c);
        }
    }
}
int solve(vector<vector<bool> > const & c) {
    int h = c.size();
    int w = c.front().size();
    vector<vector<int> > k(h, vector<int>(w, 0));
    int n = 0;
    repeat (y,h) {
        repeat (x,w) {
            if (not k[y][x] and c[y][x]) {
                dfs(x,y,++n,k,c);
            }
        }
    }
    return n;
}
int main(void) {
    while (true) {
        int w, h; cin >> w >> h;
        if (w == 0 and h == 0) break;
        vector<vector<bool> > c(h, vector<bool>(w));
        repeat (y,h) {
            repeat (x,w) {
                int t; cin >> t;
                c[y][x] = t;
            }
        }
        cout << solve(c) << endl;
    }
    return 0;
}

