class UnionFind {
    int n;
public:
    vector<int> uni;
    explicit UnionFind(int n) : uni(static_cast<u32>(n), -1) , n(n){};

    int root(int a){
        if (uni[a] < 0) return a;
        else return (uni[a] = root(uni[a]));
    }

    bool unite(int a, int b) {
        a = root(a);
        b = root(b);
        if(a == b) return false;
        if(uni[a] > uni[b]) swap(a, b);
        uni[a] += uni[b];
        uni[b] = a;
        return true;
    }
};

int main() {
    int w, h;
    while(cin >> w >> h, w|h){
        UnionFind uf(h*w);
        vector<vector<int>> v(h+2, vector<int> (w+2, 0));
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                int x;
                cin >> x;
                v[i+1][j+1] = x;
            }
        }
        auto f = [&](int p, int q){ return p*w+q; };
        int dy[] {1, 1, 1, 0, 0, -1, -1, -1},
            dx[] {-1, 0, 1, -1, 1, -1, 0, 1};
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if(v[i+1][j+1] == 0) continue;
                for (int k = 0; k < 8; ++k) {
                    if(v[i+dy[k]+1][j+dx[k]+1]){
                        uf.unite(f(i, j), f(i+dy[k], j+dx[k]));
                    }
                }
            }
        }
        set<int> s;
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if(v[i+1][j+1]) s.insert(uf.root(f(i, j)));
            }
        }
        cout << s.size() << "\n";
    }
    return 0;
}

