//parent[i]:ノード番号iの親のノード番号
//親が存在しないときは-(属するグループのサイズ)を格納
//parent = vector<int>(N, -1);で初期化
vector<int> parent;
//ノードXの根を返す
int root(int X){
	if(parent[X] < 0)return X;
	return parent[X] = root(parent[X]);
}
//ノードXが属するグループのサイズ(属するノード数)を返す
int size(int X){
	return -parent[root(X)];
}
//Xの属するグループとYの属するグループを繋ぐ
//それぞれの根どうしを繋ぐ
bool connect(int X, int Y){
	//根同士をつなぐため指すノードを根にする
	X = root(X);
	Y = root(Y);
	//すでに繋がっているときは繋がずにfalseを返す
	if(X == Y){
		return false;
	}
	//大きいほうに小さいほうを繋ぎたいので逆ならスワップ
	if(size(X) < size(Y))swap(X, Y);
	//繋がれる方のサイズを更新
	parent[X] += parent[Y];
	//繋ぐ方の親を設定
	parent[Y] = X;
	return true;
}
int main(){

	while(true){
		int W, H;
		cin >> W >> H;
		if(W == 0 && H == 0)break;
		vector<vector<int>> C(H, vector<int>(W));
		int landNum = 0;
		for(int i = 0; i < H; i ++){
			for(int j = 0; j < W; j ++){
				cin >> C[i][j];
				if(C[i][j] == 1)landNum ++;
			}
		}
		parent = vector<int>(H * W, -1);
		for(int i = 0; i < H; i ++){
			for(int j = 0; j < W; j ++){
				if(C[i][j] == 1){
					if(i + 1 < H && C[i + 1][j] == 1)connect((i + 1) * W + j, i * W + j);
					if(i - 1 >= 0 && C[i - 1][j] == 1)connect((i - 1) * W + j, i * W + j);
					if(j + 1 < W && C[i][j + 1] == 1)connect(i * W + (j + 1), i * W + j);
					if(j - 1 >= 0 && C[i][j - 1] == 1)connect(i * W + (j - 1), i * W + j);
					if(i + 1 < H && j + 1 < W && C[i + 1][j + 1] == 1)connect((i + 1) * W + (j + 1), i * W + j);
					if(i + 1 < H && j - 1 >= 0 && C[i + 1][j - 1] == 1)connect((i + 1) * W + (j - 1), i * W + j);
					if(i - 1 >= 0 && j + 1 < W && C[i - 1][j + 1] == 1)connect((i - 1) * W + (j + 1), i * W + j);
					if(i - 1 >= 0 && j - 1 >= 0 && C[i - 1][j - 1] == 1)connect((i - 1) * W + (j - 1), i * W + j);
				}
			}
		}
		map<int, int> m;
		for(int i = 0; i < H; i ++){
			for(int j = 0; j < W; j ++){
				if(C[i][j] == 1)m[root(i * W + j)] ++;
			}
