int W, H;
bool sea_map[50][50];
bool is_reached[50][50];

void dfs(int s_wi, int s_hi) {
    if(s_wi < 0 || W <= s_wi ||
       s_hi < 0 || H <= s_hi ||
       !sea_map[s_hi][s_wi]  ||
       is_reached[s_hi][s_wi]) {
        return;
    }

    is_reached[s_hi][s_wi] = true;

    dfs(s_wi + 1, s_hi + 1);
    dfs(s_wi + 1, s_hi    );
    dfs(s_wi + 1, s_hi - 1);
    dfs(s_wi    , s_hi - 1);
    dfs(s_wi - 1, s_hi - 1);
    dfs(s_wi - 1, s_hi    );
    dfs(s_wi - 1, s_hi + 1);
    dfs(s_wi    , s_hi + 1);
}

bool search_start_point(int& s_wi, int& s_hi) {
    REP(hi, H) {
        REP(wi, W) {
            if(sea_map[hi][wi] && !is_reached[hi][wi]) {
                s_wi = wi;
                s_hi = hi;
                return true;
            }
        }
    }
    return false;
}

