            REP(wi, W) {
                std::cin >> sea_map[hi][wi];
                is_reached[hi][wi] = false;
            }
        }

        int ans = 0;
        while(true) {
            int s_wi, s_hi;
            if(!search_start_point(s_wi, s_hi)) {
                break;
            }
            else {
                dfs(s_wi, s_hi);
                ans++;
            }
        }

        std::cout << ans << std::endl;
    }

    return 0;
}

