	int w = m[0].size();
	int h = m.size();

	if(!( 0 <= i && i <= h && 0 <= j && j <= w)){
		return 0;
	}

	if(m[i][j] == 0){
		return 0;
	}
	else if(m[i][j] == 1){
		m[i][j] = 0;
		MAP(m, i - 1, j - 1);
		MAP(m, i, j - 1);
		MAP(m, i + 1, j - 1);
		MAP(m, i - 1, j);
		MAP(m, i + 1, j);
		MAP(m, i - 1, j + 1);
		MAP(m, i, j + 1);
		MAP(m, i + 1, j + 1);
	}

	return 1;
}

int main(){
	int w, h;

	while(true){
		cin >> w >> h;

		if(w == 0 && h == 0){
			break;
		}

		VVI map(h + 1, VI(w + 1, 0));

		for(int i = 0; i < h; i++){
			for(int j = 0; j < w; j++){
				cin >> map[i][j];
			}
		}

		int count = 0;

		for(int i = 0; i < h; i++){
			for(int j = 0; j < w; j++){
				count += MAP(map, i, j);
			}
		}

		cout << count << endl;
	}
}

