// 深さ優先探索
void dfs(const Graph& g, ll x, ll &cnt)
{
	seen[x] = true; // v を訪問済にする
	pa[x][0] = cnt;
	cnt++;

	 // v から行ける各頂点 next_v について
	for (auto next_x : g[x]) {
		if (seen[next_x]) continue; // next_v が探索済だったらスルー
		dfs(g, next_x, cnt); // 再帰的に探索
	}
	pa[x][1] = cnt;
	cnt++;
}

