};

squareMap::squareMap(vector<string> map) : _map(map)
{
    _h = _map.size();
    _w = _map.size() > 0 ? _map[0].size() : 0;
    setStartGoal();
}

squareMap::~squareMap()
{
}

bool squareMap::setStartGoal()
{
    // STARTとGOALを探す
    bool start_found = false, goal_found = false;
    for (int i = 0; i < _h; i++)
    {
        string::size_type pos;
        if (!start_found)
        {
            if (string::npos != (pos = _map[i].find(START)))
            {
                start_found = true;
                _start = {i, pos};
            }
        }
        if (!goal_found)
        {
            if (string::npos != (pos = _map[i].find(GOAL)))
            {
                goal_found = true;
                _goal = {i, pos};
            }
        }
        if (start_found && goal_found)
            break;
    }
    return start_found || goal_found;
}

// スタック使用深さ優先探索で，スタートからゴールにたどり着けるかどうか探索する
const bool squareMap::depthFirstSearch()
{
    // 調べる升を記録するスタック
    stack<pair<int, int>> destination;
    // スタートから各升の距離を記録 その升をすでに探索したかどうかも記録 INFは調べていないことを意味する
    vector<vector<int>> distance(_h, vector<int>(_w, INF));

    // 最初にスタートを探索した
    destination.push(_start);
    distance[_start.first][_start.second] = 0;
    _map[_start.first][_start.second] = WALL;

    // 全ての升を調べ終わるか，ゴールが見つかるまで調べる
    while (!destination.empty())
    {
        // スタックから調べる升を取り出す
        pair<int, int> p = destination.top();
        destination.pop();
        // 調べる升がゴールなら終わり
        if (p == _goal)
            break;

        // 次に調べる升の上下左右を調べる
        for (int i = 0; i < dx.size(); i++)
        {
            // np: 次に調べる升の上下左右の升
            pair<int, int> np = {p.first + dy[i], p.second + dx[i]};
            // npが枡目内に存在する，npが壁ではないかつnpをすでに探索していないか確認
            if (0 <= np.first && np.first < _h && 0 <= np.second && np.second < _w && _map[np.first][np.second] != WALL && distance[np.first][np.second] == INF)
            {
                // npを今後調べる升としてスタックに積む
                destination.push(np);
                // npまでの距離を記録する
                distance[np.first][np.second] = distance[p.first][p.second] + 1;
                // 陸を海に変える
                _map[np.first][np.second] = WALL;
            }
        }
    }
    // ゴールまでの距離がINFではない．つまりゴールへたどり着けるかどうかを返す
    return (inMap(_goal)) ? distance[_goal.first][_goal.second] != INF : false;
}

const bool squareMap::breadthFirstSearch()
{
    vector<vector<int>> tmp;
    return breadthFirstSearch(tmp);
}
const bool squareMap::breadthFirstSearch(vector<vector<int>> &return_dist)
{
    // 調べる升を記録するキュー
    queue<pair<int, int>> destination;
    // スタートから各升の距離を記録 その升をすでに探索したかどうかも記録 INFは調べていないことを意味する
    vector<vector<int>> distance(_h, vector<int>(_w, INF));

    // 最初にスタートを探索した
    destination.push(_start);
    distance[_start.first][_start.second] = 0;

    // 全ての升を調べ終わるか，ゴールが見つかるまで調べる
    while (!destination.empty())
    {
        // キューから調べる升を取り出す
        pair<int, int> p = destination.front();
        destination.pop();
        // 調べる升がゴールなら終わり
        if (p == _goal)
            break;

        // 次に調べる升の上下左右を調べる
        for (int i = 0; i < dx.size(); i++)
        {
            // np: 次に調べる升の上下左右の升
            pair<int, int> np = {p.first + dy[i], p.second + dx[i]};
            // npが枡目内に存在する，npが壁ではないかつnpをすでに探索していないか確認
            if (0 <= np.first && np.first < _h && 0 <= np.second && np.second < _w && _map[np.first][np.second] != WALL && distance[np.first][np.second] == INF)
            {
                // npを今後調べる升としてスタックに積む
                destination.push(np);
                // npまでの距離を記録する
                distance[np.first][np.second] = distance[p.first][p.second] + 1;
            }
        }
    }
    // ゴールまでの距離がINFではない．つまりゴールへたどり着けるかどうかを返す
    return_dist = distance;
    return (0 <= _goal.first && _goal.first < _h && 0 <= _goal.second && _goal.second < _w) ? distance[_goal.first][_goal.second] != INF : false;
}

// 全ての道に行くことができるか
const bool squareMap::goEntire()
{
    // 各マスへの距離を得る
    vector<vector<int>> distance;
    breadthFirstSearch(distance);

    // 到達できない道があるか調べる．もしあればすべての道に行くことはできない．
    bool can = true;
    for (int i = 0; i < _h && can; i++)
        for (int j = 0; j < _w && can; j++)
            if (_map[i][j] == PASS && distance[i][j] == INF)
                can = false;
    return can;
}

int squareMap::howMany()
{
    int count = 0;
    while (setStartGoal())
    {
        depthFirstSearch();
        count++;
    }
    return count;
}

