int count = 0;

void check_member(int i,int j,int h, int w){
    if(member[i][j] == 0 && A[i][j] == 1 && i <= h && j <= w){
        member[i][j] = count;
        check_member(  i,  j+1 , h , w);
        check_member(i+1 , j+1 , h , w);
        check_member(i+1 ,   j , h , w);
        check_member(i+1 , j-1 , h , w);
        check_member(  i , j-1 , h , w);
        check_member(i-1 , j-1 , h , w);
        check_member(i-1 ,   j , h , w);
        check_member(i-1 , j+1 , h , w);
    }else{
        return;
    }
}


