void dfs(int h, int w) {
	field[h][w] = 0;

	// 八方向を探索
	for (int dh = -1; dh <= 1; ++dh) {
		for (int dw = -1; dw <= 1; ++dw) {
			//if(dh*dw!=0) continue; //4方向にするときはここを有効に
			int nh = h + dh, nw = w + dw;

