int maps[52][52];
int w,h;
void init(){
  for(int i = 0; i < 52; i++){
    for(int j = 0; j < 52; j++){
      maps[i][j] = 0;
    }
  }
  return;
}

void search(int x, int y){
  maps[y][x] = 0;
  if(maps[y - 1][x] && y > 0){
    search(x, y -1);
  }
  if(maps[y - 1][x - 1] && x > 0 && y > 0){
    search(x - 1, y - 1);
  }
  if(maps[y][x - 1] && x > 0){
    search(x - 1, y);
  }
  if(maps[y + 1][x - 1] && y < h && x > 0){
    search(x - 1, y + 1);
  }
  if(maps[y + 1][x] && y < h){
    search(x, y + 1);
  }
  if(maps[y + 1][x + 1] && y < h && x < w){
    search(x + 1, y + 1);
  }
  if(maps[y][x + 1] && x < w){
    search(x + 1, y);
  }
  if(maps[y - 1][x + 1] && y > 0 && x < w){
    search(x + 1, y - 1);
  }
  return;
}


int main(){
  int count;
  while(true){
    cin >> w >> h;
    if( !w && !h){
      break;
    }
    count = 0;
    init();
    for(int i = 0; i < h; i++){
      for(int j = 0; j < w; j++){
	cin >> maps[i][j];
      }
    }

    for(int i = 0; i < h; i++){
      for(int j = 0; j < w; j++){
	if(maps[i][j]){
	  count++;
	  search(j,i);
	}
      }
    }

    printf("%d\n", count);
  }
  return 0;
}

