template<typename T>
vector<T> make_v(size_t a, T b) {
    return vector<T>(a, b);
}

template<typename... Ts>
auto make_v(size_t a, Ts... ts) {
    return vector<decltype(make_v(ts...))>(a, make_v(ts...));
}

void dfs(int y, int x, vector<vector<bool>> &used, vector<vector<int>> &M) {
    if (used[y][x]) return;
    used[y][x] = true;
    REP(i, -1, 2) {
        REP(j, -1, 2) {
            int ny = y + i, nx = x + j;
            if (ny < 0 || ny >= M.size() || nx < 0 || nx >= M[ny].size() || M[ny][nx] == 0) continue;
            dfs(ny, nx, used, M);
        }
    }
}

