                cin >> M[i][j];
            }
        }
        auto used = make_v(h, w, false);
        int ans = 0;
        REP(i, 0, h) {
            REP(j, 0, w) {
                if (!used[i][j] && M[i][j] == 1) {
                    dfs(i, j, used, M);
                    ans++;
                }
            }
        }
