int map[51][51],w,h;
void dfs(int y,int x){
	map[y][x] = 0;
	int tx,ty;
	for(int dx=-1;dx<=1;dx++){
		for(int dy=-1;dy<=1;dy++){
			tx = x + dx;
			ty = y + dy;
			if(tx > -1 && tx < w && ty > -1 && ty < h && map[ty][tx] == 1) dfs(ty,tx);
		}
	}
	return;

}
int main(){
