#include <iostream>
#include <vector>
using namespace std;

bool search(vector<vector<bool>>& isvisit, vector<vector<int>> c, int i, int j){
    if(!(i >= 0 && i < isvisit.size() && j >= 0 && j < isvisit[i].size())){
        return false;
    }else if(isvisit[i][j]){
        return false;
    }else{
        isvisit[i][j] = true;
        if(c[i][j] == 0) return false;

        for(int ii = -1; ii <= 1; ii += 2){
            search(isvisit, c, i+ii, j);
            search(isvisit, c, i, j+ii);
            search(isvisit, c, i+ii, j+ii);
            search(isvisit, c, i+ii, j-ii);
        }
        return true;
    }
}

int main(){
    int w, h;
    while(true){
        cin >> w >> h;
        if(w == 0 && h == 0) break;
        vector<vector<int>> c(h, vector<int>(w));
        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++) cin >> c[i][j];
        }
        int ans = 0;
        vector<vector<bool>> isvisit(h, vector<bool>(w, false));
        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++){
                if(search(isvisit, c, i, j)) ans++;
            }
        }
        cout << ans << endl;
    }

    return 0;
}

