void erase_island (int ocean[][50], int h, int w, int i, int j) {
    ocean[i][j] = 0;
    for(int dy = -1; dy <= 1; dy++) {
        for(int dx = -1; dx <= 1; dx++) {
            if (i + dy >= 0 && i + dy < h && j + dx >= 0 && j + dx < w) {
                if(ocean[i+dy][j+dx] == 1)  erase_island(ocean, h, w, i+dy, j+dx);
            }
        }
    }
}

int main() {

    int w, h;
    while(cin >> w >> h && (w || h)) {
        int ocean[h][50];
        for(int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                cin >> ocean[i][j];
            }
        }
        int answer = 0;
        for(int i = 0; i < h; i++) {
            for(int j = 0; j < w; j++) {
                if (ocean[i][j] == 1) {
                    erase_island(ocean, h, w, i, j);
                    answer += 1;
                }
            }
        }
        cout << answer << endl;
    }

    return 0;
}

