using namespace std;

int dh[] = {1, 1, 0, -1, -1, -1, 0, 1};
int dw[] = {0, 1, 1, 1, 0, -1, -1, -1};

void dfs(int h, int w, int **c, int sh, int sw, int **seen, int t) {
    seen[sh][sw] = t;

    for (int i = 0; i < 8; i++) {
        int nh = sh + dh[i], nw = sw + dw[i];
        if (nh < 0 || h <= nh || nw < 0 || w <= nw || seen[nh][nw] != -1 || c[nh][nw] == 0)
            continue;

        dfs(h, w, c, nh, nw, seen, t);
    }
}

void solve(int h, int w) {
    int **c = new int*[h];
    int **seen = new int*[h];
    for (int i = 0; i < h; i++) {
        c[i] = new int[w];
        seen[i] = new int[w];
        for (int j = 0; j < w; j++) {
            cin >> c[i][j];
            seen[i][j] = -1;
        }
    }

    int ans = 0;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (seen[i][j] == -1 && c[i][j] != 0) {
                dfs(h, w, c, i, j, seen, ans+1);
                ans++;
            }
        }
    }

    cout << ans << endl;

}

int main() {
    int h, w;
    while (1) {
        cin >> h >> w;
        if (h == 0 && w == 0)
            break;

        solve(w, h);
    }

    return 0;
}

