#include <bits/stdc++.h>
using namespace std;
enum class WalkingResult { undef, walked };
enum class LandS { sea, land };
using LMap = vector<vector<LandS>>;

void solve(int w, int h) {
    LMap lMap(h, vector<LandS>(w));
    vector<pair<int, int>> lands;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            int t;
            cin >> t;
            lMap[i][j] = t == 1 ? LandS::land : LandS::sea;
            if (t == 1) lands.push_back(make_pair(i, j));
        }
    }

    vector<vector<WalkingResult>> wMap(h, vector<WalkingResult>(w, WalkingResult::undef));
    int count = 0;
    stack<pair<int, int>> s;
    for (int i = 0; i < lands.size(); ++i) {
        pair<int, int> x = lands[i];
        bool already = wMap[x.first][x.second] == WalkingResult::walked;
        if (already) continue;
        s.push(x);
        while(!s.empty()) {
            pair<int, int> pos = s.top();
            s.pop();
            bool out = pos.first < 0 || h <= pos.first || pos.second < 0 || w <= pos.second;
            if (out) continue;
            bool sea = lMap[pos.first][pos.second] == LandS::sea;
            bool walked = wMap[pos.first][pos.second] == WalkingResult::walked;
            if (sea || walked) continue;
            wMap[pos.first][pos.second] = WalkingResult::walked;
            s.push(make_pair(pos.first + 1, pos.second));
            s.push(make_pair(pos.first - 1, pos.second));
            s.push(make_pair(pos.first, pos.second + 1));
            s.push(make_pair(pos.first, pos.second - 1));
            s.push(make_pair(pos.first - 1, pos.second - 1));
            s.push(make_pair(pos.first + 1, pos.second - 1));
            s.push(make_pair(pos.first - 1, pos.second + 1));
            s.push(make_pair(pos.first + 1, pos.second + 1));
        }
        count++;
    }
    cout << count << endl;
}

int main() {

    while (true) {
        int w, h;
        cin >> w >> h;
        if (w == 0 && h == 0) break;
        solve(w, h);
    }
    return 0;
}

