typedef long long itemType;

struct node
{long long v; struct node *next;};

void visit(stack<long long> stack, long long k, struct node *z, struct node **adj, long long id, long long val[]){
    struct node *t;
    t = new node;
    stack.push(k);
    while(!stack.empty()){
        k = stack.top();
        stack.pop();
        val[k] = ++id;
        for(t = adj[k]; t != z; t = t -> next){
            if(val[t -> v] == 0){
                stack.push(t -> v);
                val[t -> v] = -1;
            }
        }
    }
}

void search(stack<long long>stack, long long V, struct node *z, struct node **adj, long long id, long long val[], long long &comp, vector<vector<bool> > c, long long w){
    long long k;
    for(k = 1; k <= V; k++) val[k] = 0;
    for(k = 1; k <= V; k++){
        if(val[k] == 0){
            if(c[(k-1)/w + 1][((k-1)%w) + 1]) comp++;
            visit(stack, k, z, adj, id, val);
        }
    }
}

