#include <bits/stdc++.h>
using namespace std;
using ll = long long;
constexpr ll MOD = 1000000007;
constexpr ll INF = 1ll<<60;

ll field[60][60];
bool f[60][60];
ll W, H;

void dfs(ll h, ll w)
{
	if (f[h][w]) return;
	f[h][w] = true;
	for (ll i = -1; i <= 1; ++i)
		for (ll j = -1; j <= 1; ++j)
		{
			ll nw = w + i;
			ll nh = h + j;
			if (nw < 0 || nw > W || nh < 0 || nh > H) continue;
			if (field[nh][nw])
				dfs(nh, nw);
		}
}

int main(int argc, char **argv)
{
	while (cin >> W >> H, true)
	{
		if (W == 0 && H == 0) break;
		memset(f, 0, sizeof f);
		memset(field, 0, sizeof field);

		vector<pair<ll, ll>> search;
		search.reserve(50*50);
		for (ll h = 0; h < H; ++h)
			for (ll w = 0; w < W; ++w)
			{
				cin >> field[h][w];
				if (field[h][w] == 1)
				{
					search.push_back(pair<ll, ll>(h, w));
					// std::cout << "(h, w) : " << h << ", " << w << std::endl;
				}
			}

		ll res{0};
		for (ll i = 0; i < (ll)search.size(); ++i)
		{
			if (!f[search[i].first][search[i].second])
			{
				// std::cout << "(h, w) : " << search[i].first << ", " << search[i].second << std::endl;
				dfs(search[i].first, search[i].second);
				++res;
			}
		}
		std::cout << res << std::endl;

	}
}

