        int dy[8] = {1, 0, -1, 0, 1, 1, -1, -1};
        int dx[8] = {0, 1, 0, -1, 1, -1, 1, -1};

        //通過済みかどうか
        bool psd[55][55];

        for (int i = 0; i <= 53; i++) {
            for (int j = 0; j <= 53; j++) psd[i][j] = false;
        }

