                        for (int dir = 0; dir < 8; dir++) {

                            if (vy[inf - 1][i] + dy[dir] != -1 && vy[inf - 1][i] + dy[dir] != Y + 2 && vx[inf - 1][i] + dx[dir] != -1 && vx[inf - 1][i] + dx[dir] != X + 2) {
