bool earth[51][51];

void erase_island(int h, int w) {
    earth[h][w] = false;
    //cout << "# " << h << " " << w << endl;
    if(earth[h - 1][w - 1]) erase_island(h - 1, w - 1);
    if(earth[h - 1][w]) erase_island(h - 1, w);
    if(earth[h - 1][w + 1]) erase_island(h - 1, w + 1);
    if(earth[h][w + 1]) erase_island(h, w + 1);
    if(earth[h + 1][w + 1]) erase_island(h + 1, w + 1);
    if(earth[h + 1][w]) erase_island(h + 1, w);
    if(earth[h + 1][w - 1]) erase_island(h + 1, w - 1);
    if(earth[h][w - 1]) erase_island(h, w - 1);
}

int main() {
    int w, h;
    cin >> w >> h;
    rep(i, h) rep(j, w) {
        int temp;
        cin >> temp;
        if(temp == 0) earth[i][j] = false;
        else earth[i][j] = true;
    }

    int ans = 0;
    rep(i, h) rep(j, w) {
        if(earth[i][j]) erase_island(i , j), ++ans;
    }

    cout << ans << endl;
}

