void kazoe(int p,int P, int box[50][50]){
  if(box[p][P+1]==1){
    box[p][P+1]=0;
    P=P+1;
    kazoe(p,P,box);
  }
  if(box[p+1][P+1]==1){
    box[p+1][P+1]=0;
    P=P+1;
    p=p+1;
 kazoe(p,P,box);
  }
  if(box[p+1][P]==1){
    box[p+1][P]=0;
    p=p+1;
 kazoe(p,P,box);
  }
  if(box[p+1][P-1]==1){
    box[p+1][P-1]=0;
    P=P-1;
    p=p+1;
 kazoe(p,P,box);
  }
  if(box[p][P-1]==1){
    box[p][P-1]=0;
    P=P-1;
 kazoe(p,P,box);
  }
  if(box[p-1][P-1]==1){
    box[p-1][P-1]=0;
    P=P-1;
    p=p-1;
 kazoe(p,P,box);
  }
  if(box[p-1][P]==1){
    box[p-1][P]=0;
    p=p-1;
 kazoe(p,P,box);
  }
  if(box[p-1][P+1]==1){
    box[p-1][P+1]=0;
    P=P+1;
    p=p-1;
 kazoe(p,P,box);
  }
}
