    while(true){
        int w, h;
        cin >> w >> h;
        if(w == 0 && h == 0){
            break;
        }
        vector<vector<int> > graph(h, vector<int>(w)); 
        rep(i, h){
            rep(j, w){
                cin >> graph[i][j];
            }
        }
        vector<vector<int> > visit(h, vector<int>(w));
        int ans = 0;
        rep(i, h){
            rep(j, w){
                ans += dfs(i, j, graph, visit, h, w);
            }
        }
        cout << ans << endl;
    }

    return 0;
}

