void del(int h,int w,int height,int width){
  int i,j;
  map[h][w]=0;
  for(i=-1;i<=1;i++){
    for(j=-1;j<=1;j++){
      if((i==0 && j==0)|| h+i<0 || w+j<0 || h+i>=height || w+j>=width)continue;
      if(map[i+h][j+w]==1)del(i+h,w+j,height,width);
    }
  }
}

