int visit(int i,int j){
  c[i][j]=0;
  if((i+1)<w){
    if(c[i+1][j]) visit(i+1,j);
    if((j+1)<h) if(c[i+1][j+1]) visit(i+1,j+1);
    if((j-1)>=0) if(c[i+1][j-1]) visit(i+1,j-1);
  }
  if((j+1)<h)if(c[i][j+1]) visit(i,j+1);
  if((i-1)>=0){
    if(c[i-1][j]) visit(i-1,j);
    if((j-1)>=0) if(c[i-1][j-1]) visit(i-1,j-1);
    if((j+1)<h) if(c[i-1][j+1]) visit(i-1,j+1);
  }
  if((j-1)>=0) if(c[i][j-1]) visit(i,j-1);

  return 0;
}

