void Search(int **map, int pos_x, int pos_y, int h, int w) {
	int i,j;

	map[pos_y][pos_x]=0;

	for(i=pos_x-1;i<=pos_x+1;i++) {
		for(j=pos_y-1;j<=pos_y+1;j++) {
			if(i>=0&&j>=0&&i<w&&j<h&&map[j][i]==1)
				Search(map,i,j,h,w);
		}
	}
}

int main() {

	int w,h;
	int i,j,**map,count;
	int pos_x,pos_y;

	for(;;) {
		scanf("%d %d",&w,&h);
		if(!w&&!h) break;

		map=malloc(h*sizeof(int));
		for(i=0;i<h;i++) {
			map[i]=(int *)malloc(w*sizeof(int));
		}

		for(i=0;i<h;i++)
			for(j=0;j<w;j++)
				scanf("%d",&map[i][j]);

		count=0;
		for(pos_x=0;pos_x<w;pos_x++) {
			for(pos_y=0;pos_y<h;pos_y++) {
				if(map[pos_y][pos_x]==1) {
					count++;
					Search(map,pos_x,pos_y,h,w);
				}
			}
		}
		printf("%d\n",count);
	}
		return 0;
	}

