int map[51][51];
void search(int i,int j)
{
  if(map[i+1][j] == 1){
    map[i+1][j] = map[i][j];
    search(i+1,j);
  }
  if(map[i][j+1] == 1){
    map[i][j+1] = map[i][j];
    search(i,j+1);
  }
  if(map[i+1][j+1] == 1){
    map[i+1][j+1] = map[i][j];
    search(i+1,j+1);
  }
  if(j > 0){
    if(map[i][j-1] == 1){
      map[i][j-1] = map[i][j];
      search(i,j-1);
    }
    if(map[i+1][j-1] == 1){
      map[i+1][j-1] = map[i][j];
      search(i+1,j-1);
    }
  }
  if(i > 0){
    if(map[i-1][j] == 1){
      map[i-1][j] = map[i][j];
      search(i-1,j);
    }
    if(map[i-1][j+1] == 1){
      map[i-1][j+1] = map[i][j];
      search(i-1,j+1);
    }
  }
  if(i > 0 && j > 0){
    if(map[i-1][j-1] == 1){
      map[i-1][j-1] = map[i][j];
      search(i-1,j-1);
    }
  }
}
