int func(int x[][50],int i,int j,int flag){

  if(flag==1) return 1;

  if(x[i-1][j]==1&&i>=1){
    x[i-1][j]=0;
    func(x,i-1,j,0);
  }
  if(x[i+1][j]==1){
    x[i+1][j]==0;
    func(x,i+1,j,0);
  }
  if(x[i][j+1]==1){
    x[i][j+1]=0;
    func(x,i,j+1,0);
  }
  if(x[i][j-1]==1&&j>=1){
    x[i][j-1]=0;
    func(x,i,j-1,0);
  }
  if(x[i-1][j-1]==1&&i>=1&&j>=1){
    x[i-1][j-1]=0;
    func(x,i-1,j-1,0);
  }
  if(x[i-1][j+1]==1&&i>=1){
    x[i-1][j+1]=0;
    func(x,i-1,j+1,0);
  }
  if(x[i+1][j-1]==1&&j>=1){
    x[i+1][j-1]=0;
    func(x,i+1,j-1,0);
  }
  if(x[i+1][j+1]==1){
    x[i+1][j+1]=0;
    func(x,i+1,j+1,0);
  }
  return func(x,i,j,1);
}

