int serch(int x,int y,int w,int h){
	int i,j;
	if(c[x][y]==0||d[x][y]==1)return 0;
	d[x][y]=1;
	for(i=x-1; i<=x+1; i++){
		for(j=y-1; j<=y+1; j++){
			if(i>=0&&i<w&&j>=0&&j<h)serch(i,j,w,h);
		}
	}
	return 1;
}

