void fill(int y, int x)
{
    point p;

    init(); search(y, x);

    while(!empty())
    {
        p = get(); x = x(p), y = y(p);

        if(x-1 >= 0){
            if(y-1 >= 0 && map[y-1][x-1]) search(y-1, x-1);
            if(            map[y  ][x-1]) search(y  , x-1);
            if(y+1 <  h && map[y+1][x-1]) search(y+1, x-1);
        }

        if(y-1 >= 0 && map[y-1][x]) search(y-1, x);
        if(y+1 < h  && map[y+1][x]) search(y+1, x);

        if(x+1 < w)
        {
            if(y-1 >= 0 && map[y-1][x+1]) search(y-1, x+1);
            if(            map[y  ][x+1]) search(y  , x+1);
            if(y+1 <  h && map[y+1][x+1]) search(y+1, x+1);
        }
    }
}

