void fill(int sx, int sy)
{
    struct queue q;
    init(&q);
    enqueue(&q, sx);
    enqueue(&q, sy);
    c[sx][sy] = 0;

    while (q.head != (q.tail + 1) % BUFFER_SIZE) {
        int i;
        int x, y;
        x = dequeue(&q);
        y = dequeue(&q);

        for (i = 0; i < 8; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 0 || w <= nx || ny < 0 || h <= ny)
                continue;
            if (c[ny][nx] == 0)
                continue;

            c[ny][nx] = 0;
            enqueue(&q, nx);
            enqueue(&q, ny);
        }
    }
}

