void fill(int sx, int sy)
{
    struct queue q;
    init(&q);
    enqueue(&q, sx);
    enqueue(&q, sy);
    c[sy][sx] = 0;

    while (q.head != (q.tail + 1) % BUFFER_SIZE) {
        int i;
        int x, y;
        x = dequeue(&q);
        y = dequeue(&q);

        for (i = 0; i < 8; i++) {
