        if (w == 0 && h == 0) return
        val state = Array(h){ readLine()!!.trim().split(' ').map{it == "1"}.toBooleanArray()}
        val union = UnionFind(w * h)
        for (i in 0 until h) for (j in 0 until w) if (state[i][j]) {
            for (di in -1 .. 1) for (dj in -1 .. 1) if (i + di in 0 until h && j + dj in 0 until w && state[i + di][j + dj]){
                union.merge(i * w + j, i * w + j + di * w + dj)
            }
        }
        println((0 until h).sumBy{i -> (0 until w).count{j -> state[i][j] && union.findRoot(i * w + j) == i * w + j}})
    }
