	static int ans;
	public static void main(String arg[])
	{
		Scanner in=new Scanner(System.in);
		for(;;)
		{
			W=in.nextInt();
			H=in.nextInt();
			if((W|H)==0)
				return;
			b=new int[H][W];
			for(int i=0;i<H;i++)
				for(int j=0;j<W;j++)
					b[i][j]=in.nextInt();
