public class Main {

	static boolean[][] visited;
	static int[][] island;
	static int cnt = 0;
	static int h,w;

	public static void main(String[] args) {
		try(Scanner sc = new Scanner(System.in)) {
			while(true) {
				w = sc.nextInt();
	    		h = sc.nextInt();
				if(h == 0 && w == 0)	break;
				island = new int[h][w];
				visited = new boolean[h][w];

				for(int i=0;i<h;i++) {
					for(int j=0; j<w; j++) {
						island[i][j] = sc.nextInt();	
					}
	            }
                cnt = 0;
				for(int i=0;i<h;i++) {
					for(int j=0; j<w; j++) {
						if(island[i][j] == 1 && !visited[i][j]) {
						visit(i,j);
						cnt++;
						}
					}
				}

				System.out.println(cnt);
				}



		}
	}
	static void visit(int m,int n) {
		if(!visited[m][n]) {
            visited[m][n] = true;

			if(n+1 < w && island[m][n+1] == 1) {
				visit(m,n+1);
			}if(n-1 >= 0 && island[m][n-1] == 1) {
				visit(m,n-1);
			}if(m+1 < h && island[m+1][n] == 1) {
				visit(m+1,n);
			}if(m-1 >= 0 && island[m-1][n] == 1) {
				visit(m-1,n);
			}if(m+1 < h && n+1 < w && island[m+1][n+1] == 1) {
				visit(m+1,n+1);
			}if(m+1 < h && n-1 >= 0 && island[m+1][n-1] == 1) {
				visit(m+1,n-1);
			}if(m-1 >= 0 && n+1 < w && island[m-1][n+1] == 1) {
				visit(m-1,n+1);
			}if(m-1 >= 0 && n-1 >= 0 && island[m-1][n-1] == 1) {
				visit(m-1,n-1);
			}
		}
	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

class Main{
    static List<Node> list = new ArrayList();

    public static void main(String args[]) {
        Scanner scan = new Scanner(System.in);
        while (true) {
            int w = scan.nextInt();
            int h = scan.nextInt();
            if (w == 0 && h == 0) {
                break;
            }
            int[][] c = new int[h][w];
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    c[i][j] = scan.nextInt();
                }
            }
            int count = 0;
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if (c[i][j] == 1) {
                        c=addList(c, list, i, j, h, w);
                        while (true) {
                            if (list.size() == 0) {
                                break;
                            }
                            Node node = list.get(0);
                            list.remove(0);
                            c=addList(c, list, node.y, node.x, h, w);
                        }
                        count++;
                    }

                }
            }
            System.out.println(count);
        }
    }

    private static int[][] addList(int[][] c, List list, int i, int j, int h, int w) {
        for (int y = -1; y < 2; y++) {
            for (int x = -1; x < 2; x++) {
                if (i + y < 0 || j + x < 0 || i + y >= h || j + x >= w) {
                    continue;
                }
                if (x == 0 && y == 0) {
                    continue;
                }
                if (c[i + y][j + x] == 1) {
                    c[i + y][j + x] = 0;
                    Node node = new Node();
                    node.setX(j + x);
                    node.setY(i + y);
                    list.add(node);
                }
            }
        }
        return c;
    }
}

class Node {
    int x, y;

    public void setX(int a) {
        x = a;
    }

    public void setY(int a) {
        y = a;
    }

    public int getX() {
        return x;
    }

    public int getY() {
        return y;
    }
}

