import static java.lang.Math.*;
public class Main {
    public static void main(String[] $) {
        int[] dx={0,1,1,1,0,-1,-1,-1};
        int[] dy={-1,-1,0,1,1,1,0,-1};
        while (true) {
            int w = sc.nextInt(), h = sc.nextInt();
            if(w==0&&h==0)break;
            UF.Init(w*h);
            int[][] land=new int[h][w];
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    land[i][j]=sc.nextInt();
                }
            }
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if(land[i][j]==0)continue;
                    for (int k = 0; k < 8; k++) {
                        int row=i+dx[k],column=j+dy[k];
                        if(d(w,h,column,row)&&land[row][column]==1){
                            UF.unite(i*w+j,row*w+column);
                            //out.println((i*w+j)+"と"+(row*w+column));
                        }
                    }
                }
            }
            HashSet<Integer> set=new HashSet<>();
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if(land[i][j]==1){
                        set.add(UF.find(i*w+j));
                        //out.println("元:"+UF.find(i*w+j));
                    }
                }
            }
            out.println(set.size());
        }
        out.close();
    }

    static PrintWriter out = new PrintWriter(System.out);

    static class sc {
        static Scanner s = new Scanner(System.in);

        static String next() {
            return s.next();
        }

        static int nextInt() {
            return Integer.parseInt(s.next());
        }

        static long nextLong() {
            return Long.parseLong(s.next());
        }

        static double nextDouble() {
            return Double.parseDouble(s.next());
        }
    }

    static boolean d(int w,int h,int column,int row){
        return 0<=column&&column<w&&0<=row&&row<h;
    }
    static class UF {
        static int[] d;

        static void Init(int size) {
            d = new int[size];
            for (int i = 0; i < size; i++) {
                d[i] = -1;
            }
        }

        static boolean unite(int x, int y) {
            x = find(x);
            y = find(y);
            if (x == y) return false;
            if (d[x] > d[y]) {
                int t = d[y];
                d[y] = d[x];
                d[x] = t;
            }
            d[x] += d[y];
            d[y] = x;
            return true;
        }

        static boolean same(int x, int y) {
            return find(x) == find(y);
        }

        static int find(int k) {
            return d[k] < 0 ? k : (d[k] = find(d[k]));
        }

        static int size(int k) {
            return -d[find(k)];
        }
    }
}

import java.util.*;
public class Main {

	public static void main(String[] args) {
		int[] dx = { 0, 1,1,1,0,-1,-1,-1};
		int[] dy = {-1,-1,0,1,1, 1, 0,-1};
		Scanner sc = new Scanner(System.in);

		while (true) {
			int w = sc.nextInt();
			int h = sc.nextInt();
			if ((w | h) == 0) break;
			int[][] map = new int[h][w];
			boolean[][] check = new boolean[h][w];
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					map[i][j] = sc.nextInt();
				}
			}
			int ans = 0;
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {

					if (map[i][j] == 0 || check[i][j]) continue;

					check[i][j] = true;
					ans++;
					Queue<Integer> queueX = new LinkedList<Integer>();
					Queue<Integer> queueY = new LinkedList<Integer>();

					queueX.add(j);
					queueY.add(i);

					while (!queueX.isEmpty()) {

						int x = queueX.poll();
						int y = queueY.poll();

						for (int k = 0; k < dx.length; k++) {
							int nextX = x + dx[k];
							int nextY = y + dy[k];

