public class Main {

	static int W;
	static int H;
	static int[][] MAP ;

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		Scanner sc = new Scanner(System.in);
		while(sc.hasNext()){
			// 整数の入力
			W = Integer.parseInt(sc.next());
			H = Integer.parseInt(sc.next());
			if(W==0 && H==0)break;
			MAP = new int[H][W];

			for(int h=0; h<H; h++){
				for(int w=0; w<W; w++){
					MAP[h][w] = Integer.parseInt(sc.next());
				}
			}
			int ans=0;

			for(int h=0; h<H; h++){
				for(int w=0; w<W; w++){
					if(MAP[h][w]==1){
						dfs(w,h);
						ans++;
					}
				}
			}


			System.out.println(ans);
		}
		sc.close();
	}

	public static void dfs(int w, int h){
		if(w<0 || w>=W || h<0 || h>=H)return;
		if(MAP[h][w] == 0)return;
		MAP[h][w] = 0;
		for(int dh=-1; dh<2; dh++){
			for(int dw=-1; dw<2; dw++){
				dfs(w+dw, h+dh);
			}
		}
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Set;

public class Main {
    private final int[][] search = new int[][]{
            {0, 1},
            {0, -1},
            {1, 1},
            {1, -1},
            {1, 0},
            {-1, 1},
            {-1, 0},
            {-1, -1}
    };

    public static void main(final String[] args) throws IOException {
        new Main().run();
    }

    private void run() throws IOException {
        boolean b = true;
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        while (b) {
            b = runOnce(reader);
        }

        reader.close();
    }

    private boolean runOnce(final BufferedReader reader) throws IOException {
        final String[] params = reader.readLine().split(" ");
        final int x = Integer.parseInt(params[0]);
        final int y = Integer.parseInt(params[1]);
        if (x == 0 && y == 0) return false;
        final Set<Field> fields = new HashSet<>();
        for (int i = 0; i < y; i++) {
            final String[] line = reader.readLine().split(" ");
            for (int j = 0; j < line.length; j++) {
                fields.add(new Field(i, j, line[j].equals("1")));
            }
        }
        int landCount = 0;
        while (true) {
            final Iterator<Field> iterator = fields.iterator();
            if (!iterator.hasNext()) {
                break;
            }
            final Field next = iterator.next();
            if (next.land) {
                searchLand(next, fields);
                landCount++;
            } else {
                fields.remove(next);
            }
        }
        System.out.println(landCount);
        return true;
    }

    private void searchLand(final Field field, final Set<Field> fields) {
        fields.remove(field);

        final Field tmp = new Field(0, 0, true);
        for (final int[] s: search) {
            tmp.x = field.x + s[0];
            tmp.y = field.y + s[1];
            if(fields.contains(tmp)) {
                searchLand(tmp, fields);
                fields.remove(tmp);
            }
        }
    }

    private final class Field {
        int x, y;
        boolean land;

        Field(final int x, final int y, final boolean land) {
            this.x = x;
            this.y = y;
            this.land = land;
        }

        @Override
        public int hashCode() {
            return x + y * 100;
        }

        @Override
        public boolean equals(final Object obj) {
            if (obj instanceof Field) {
                return ((Field) obj).x == this.x && ((Field) obj).y == this.y && this.land == ((Field) obj).land;
            }
            return super.equals(obj);
        }
    }
}

import java.util.Scanner;

class Sea {
	private int w;
	private int h;
	private int atlas[][];
	public Sea(int w, int h, int[][] atlas) {
		this.w = w;
		this.h = h;
		this.atlas = atlas;
	}
	// atlasに破壊的操作を及ぼす. もしそうでありたくないのであれば, 
	// clone()でshallow copyを作るとかの実装にしなければいけない. 
	// その場合は, メモリ消費に気をつける. 
	private void dfs(int x, int y) {
		atlas[x][y] = 0;
		for (int dx = -1; dx <= 1; ++dx) {
			for (int dy = -1; dy <= 1; ++dy) {
				int nx = x + dx; int ny = y + dy;
				if (out(nx, ny)) continue;
				if (atlas[nx][ny] == 1) dfs(nx, ny);
			}
		}
	}
	public boolean in(int x, int y) {
		return (0 <= x && x < h) && (0 <= y && y < w);
	}
	public boolean out(int x, int y) {
		return !in(x, y);
	}
	public int countIsland() {
		int cnt = 0;
		for (int x = 0; x < h; ++x)
			for (int y = 0; y < w; ++y)
				if (atlas[x][y] == 1) {
					dfs(x, y);
					++cnt;
				}
		return cnt;
	}
}

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		StringBuilder out = new StringBuilder();
		while (true) {
			int w = sc.nextInt();
			int h = sc.nextInt();
			if (w == 0 && h == 0) break;
			int atlas[][] = new int[h][w];
			for (int i = 0; i < h; ++i)
				for (int j = 0; j < w; ++j)
					atlas[i][j] = sc.nextInt();
			Sea sea = new Sea(w, h, atlas);
			out.append(sea.countIsland() + "\n");
		}
		System.out.print(out);
	}
}

