import java.io.*;
import java.util.*;

public class Main {
	FastScanner in = new FastScanner(System.in);
	PrintWriter out = new PrintWriter(System.out);

	int[] vx = {1, 0, -1, -1, 1, -1, 0, 1};
	int[] vy = {-1, -1, -1, 0, 0, 1, 1, 1};
	int n, m;

	int[][] map;
	boolean[][] visited;

	void dfs(int x, int y) {
		if (visited[y][x]) return;

		visited[y][x] = true;
		for (int d = 0; d < vx.length; d++) {
			int nx = x + vx[d], ny = y + vy[d];
			if (0 <= nx && nx < m && 0 <= ny && ny < n && map[ny][nx] == 1) {
				dfs(nx, ny);
			}
		}
	}

	public void run() {
		while (true) {
			m = in.nextInt();
			n = in.nextInt();
			if (m == 0) break;

			map = new int[n][];
			for (int i = 0; i < n; i++) 
				map[i] = in.nextIntArray(m);

			int res = 0;
			visited = new boolean[n][m];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (map[i][j] == 1 && !visited[i][j]) {
						dfs(j, i);
						res++;
					}
				}
			}
			System.out.println(res);
		}
		out.close();
	}

	public static void main(String[] args) {
		new Main().run();
	}

	public void mapDebug(int[][] a) {
		System.out.println("--------map display---------");

		for (int i = 0; i < a.length; i++) {
			for (int j = 0; j < a[i].length; j++) {
				System.out.printf("%3d ", a[i][j]);
			}
			System.out.println();
		}

		System.out.println("----------------------------");
		System.out.println();
	}

	public void debug(Object... obj) {
		System.out.println(Arrays.deepToString(obj));
	}

	class FastScanner {
		private InputStream stream;
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;

		public FastScanner(InputStream stream) {
			this.stream = stream;
			//stream = new FileInputStream(new File("dec.in"));

		}

		int read() {
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		boolean isSpaceChar(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		boolean isEndline(int c) {
			return c == '\n' || c == '\r' || c == -1;
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		int[] nextIntArray(int n) {
			int[] array = new int[n];
			for (int i = 0; i < n; i++)
				array[i] = nextInt();

			return array;
		}

		long nextLong() {
			return Long.parseLong(next());
		}

		long[] nextLongArray(int n) {
			long[] array = new long[n];
			for (int i = 0; i < n; i++)
				array[i] = nextLong();

			return array;
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		double[] nextDoubleArray(int n) {
			double[] array = new double[n];
			for (int i = 0; i < n; i++)
				array[i] = nextDouble();

			return array;
		}

		String next() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		String[] nextStringArray(int n) {
			String[] array = new String[n];
			for (int i = 0; i < n; i++)
				array[i] = next();

			return array;
		}

		String nextLine() {
			int c = read();
			while (isEndline(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isEndline(c));
			return res.toString();
		}
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

	int[][] map;

	int w, h;

	// 遷移ベクトル
	int[] ax = { -1, 0, 1, 1, 1, 0, -1, -1 };
	int[] ay = { -1, -1, -1, 0, 1, 1, 1, -1 };

	void run() {
		Scanner sc = new Scanner(System.in);

		while (true) {
			w = sc.nextInt();
			h = sc.nextInt();

			// w=0かつh=0だと必ず0になる(bit演算の論理和)
			if ((w | h) == 0) {
				break;
			}

			map = new int[h][w];

			for (int j = 0; j < h; j++) {
				for (int i = 0; i < w; i++) {
					map[j][i] = sc.nextInt();
				}
			}

			int cnt = 0;

			for (int j = 0; j < h; j++) {
				for (int i = 0; i < w; i++) {
					if (map[j][i] == 1) {
						search(i, j);
						// System.out.println("i = " + i + ", j = " + j);
						// debug();
						cnt++;
					}
				}
			}

			System.out.println(cnt);

		}

	}

	public static void main(String[] args) {

		new Main().run();

	}

	public void search(int x, int y) {

		if (x < 0 || y < 0 || x >= w || y >= h || map[y][x] == 0) {
			return;
		}

		map[y][x] = 0;

		for (int i = 0; i < 8; i++) {
			int nx = x + ax[i];
			int ny = y + ay[i];
			search(nx, ny);
		}
	}

	public void debug() {
		// test
		System.out.println("---------------");
		for (int j = 0; j < h; j++) {
			for (int i = 0; i < w; i++) {
				System.out.print(map[j][i] + " ");
			}
			System.out.println();
		}
		System.out.println("---------------");
	}
}

