                for (int j = 0; j < W; j++) {
                    map[i][j] = sc.nextInt();
                }
            }

            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (map[i][j] > 0) {
                        count++;
                        floodFill(i,j);
                    }
                }
            }

            System.out.println(count);
        }
    }

    public static void floodFill(int i, int j) {
        if (i < 0 || i >= H || j < 0 || j >= W) return;
        if (map[i][j] == 0) return;
        map[i][j] = 0;
        for (int x = 0; x < 8; x++) {
            floodFill(i + iAdj[x], j + jAdj[x]);
        }
    }
