			for(int i = 0; i < h; i++) {
				for(int j = 0; j < w; j++) {
					if(map[i][j]) {
						counter++;
						sorv(i,j);
					}

				}
			}
			System.out.println(counter);

		}
	}

	static void sorv(int i, int j) {
		if(i < 0 || j < 0)return;
		if(i >= map.length || j >= map[i].length)return;
		if(!map[i][j])return;
		if(map[i][j]) map[i][j] = false;
		sorv(i-1,j-1);
		sorv(i-1,j);
		sorv(i-1,j+1);
		sorv(i,j+1);
		sorv(i,j-1);
		sorv(i+1,j-1);
		sorv(i+1,j);
		sorv(i+1,j+1);
	}
