		    while(! (s[0].isEmpty() && s[1].isEmpty())){
			//System.out.println("＠"+x+" "+y);
			x = (Integer)s[0].pop();
			y = (Integer)s[1].pop();
			if(field[x][y]==1){
			    field[x][y] = -1; //通過済
			    search(s, field, x, y, w, h);
			}
		    }
		}
	    }
	}
	System.out.println(count);
    }

    static void search(Stack[] s, int[][]field, int x, int y, int w, int h){
	if(x+1<w && (field[x+1][y]==1)){      //右
	    s[0].push(x+1);
	    s[1].push(y);
	}
	if(x-1>=0 && field[x-1][y]==1){   //左
	    s[0].push(x-1);
	    s[1].push(y);
	}
	if(y+1<h && field[x][y+1]==1){    //上
	    s[0].push(x);
	    s[1].push(y+1);
	}
	if(y-1>=0 && field[x][y-1]==1){    //下
	    s[0].push(x);
	    s[1].push(y-1);
	}
	if(x+1<w && y+1<h && field[x+1][y+1]==1) { //右上
	    s[0].push(x+1);
	    s[1].push(y+1);
	}
	if(x+1<w && y-1>=0 && field[x+1][y-1]==1) { //右下
	    s[0].push(x+1);
	    s[1].push(y-1);
	}
	if(x-1>=0 && y+1<h && field[x-1][y+1]==1){  //左上
	    s[0].push(x-1);
	    s[1].push(y+1);
	}
	if(x-1>=0 && y-1>=0 && field[x-1][y-1]==1){ //左下
	    s[0].push(x-1);
	    s[1].push(y-1);
	}
    }
}

class Stack{
    Object[] stack;
    int sp;
    public Stack(int n){
	stack = new Object[n];
	sp = 0;
    }
    public void push(Object x){
	stack[sp++] = x;
    }
    public Object pop(){
	return stack[--sp];
    }
    public boolean isEmpty(){
	return sp == 0;
    }
}

import java.util.*;

class Coordinate{
    private int x, y;
    public void set(int x_cor, int y_cor){
        x = x_cor;
        y = y_cor;
    }

    public boolean exist(int x_cor, int y_cor){
        if (x == x_cor && y == y_cor){
            return true;
        }
        return false;
    }
}

class Island {
    private HashSet<Coordinate> coordinates = new HashSet<Coordinate>();

    public void new_coords(int x_cor, int y_cor) {
        Coordinate f_coordinate = new Coordinate();
        f_coordinate.set(x_cor, y_cor);
        coordinates.add(f_coordinate);
    }

    public HashSet<Coordinate> getCoordinates(){
        return coordinates;
    }

    public void clear(){
        coordinates.clear();
    }

    public boolean adjacent(int x_cor, int y_cor) {
        Iterator<Coordinate> iterator = coordinates.iterator();
        while (iterator.hasNext()) {
            Coordinate tmp_coords = iterator.next();
            for (int i = -1; i <= 1; i++) {
                for (int j = -1; j <= 1; j++) {
                    if (tmp_coords.exist(x_cor + i, y_cor + j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    public void merge(Island target){
        coordinates.addAll(target.getCoordinates());
        target.clear();
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            HashSet<Island> islands = new HashSet<Island>();
            int w = sc.nextInt(), h = sc.nextInt();
            if (w == 0 && h == 0) break;
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if (sc.nextInt() == 1) {
                        Island tmp_island = new Island();
                        tmp_island.new_coords(i, j);
                        HashSet<Island> removing = new HashSet<Island>();
                        Iterator<Island> iterator = islands.iterator();
                        while (iterator.hasNext()) {
                            Island iter_island = iterator.next();
                            if (iter_island.adjacent(i, j)) {
                                tmp_island.merge(iter_island);
                                removing.add(iter_island);
                            }
                        }
                        islands.removeAll(removing);
                        islands.add(tmp_island);
                    }
                }
            }
            System.out.println(islands.size());
        }
    }
}

