    static void solve(int w, int h){
	int[][] field = new int[w][h];
	int i, j;
	for(i=0; i<h; i++){
	    for(j=0; j<w; j++){
		field[j][i] = kbd.nextInt();  // 0:海  1:陸
		//System.out.print(field[j][i]);
	    }
	    //System.out.println();
	}

	Stack[] s = new Stack[2];
	s[0] = new Stack(w*h+10);
	s[1] = new Stack(w*h+10);
	int count = 0;
	for(i=0; i<w; i++){
	    for(j=0; j<h; j++){
		int x = i;
		int y = j;
		if(field[x][y]==1) {
		    count++;
		    //System.out.println(x+" "+y);
		    search(s, field, x, y, w, h);
		    while(! (s[0].isEmpty() && s[1].isEmpty())){
