			    field[x][y] = -1; //通過済
			}
			search(s, field, x, y, w, h);
		    }
		}
	    }
	}
	System.out.println(count);
    }

    static void search(Stack[] s, int[][]field, int x, int y, int w, int h){
	if(x+1<w && (field[x+1][y]==1)){      //右
	    s[0].push(x+1);
	    s[1].push(y);
	}
	if(x-1>=0 && field[x-1][y]==1){   //左
	    s[0].push(x-1);
	    s[1].push(y);
	}
	if(y+1<h && field[x][y+1]==1){    //上
	    s[0].push(x);
	    s[1].push(y+1);
	}
	if(y-1>=0 && field[x][y-1]==1){    //下
	    s[0].push(x);
	    s[1].push(y-1);
	}
	if(x+1<w && y+1<h && field[x+1][y+1]==1) { //右上
	    s[0].push(x+1);
	    s[1].push(y+1);
	}
	if(x+1<w && y-1>=0 && field[x+1][y-1]==1) { //右下
	    s[0].push(x+1);
	    s[1].push(y-1);
	}
	if(x-1>=0 && y+1<h && field[x-1][y+1]==1){  //左上
	    s[0].push(x-1);
	    s[1].push(y+1);
	}
	if(x-1>=0 && y-1>=0 && field[x-1][y-1]==1){ //左下
	    s[0].push(x-1);
	    s[1].push(y-1);
	}
    }
}

class Stack{
    Object[] stack;
    int sp;
    public Stack(int n){
	stack = new Object[n];
	sp = 0;
    }
    public void push(Object x){
	stack[sp++] = x;
    }
    public Object pop(){
	return stack[--sp];
    }
    public boolean isEmpty(){
	return sp == 0;
    }
}

