		void dfs() {
			Point bufPoint=null;

			while(!data.isEmpty()) {

				bufPoint=data.pop();


				int nowY=bufPoint.getY();
				int nowX=bufPoint.getX();

				isReached[nowY][nowX]=true;


				int nextY=0;
				int nextX=0;

				int[] dy= {1,1,0,-1,-1,-1,0,1};
				int[] dx= {0,1,1,1,0,-1,-1,-1,0};

				for(int d=0;d<8;d++) {
					nextY=nowY+dy[d];
					nextX=nowX+dx[d];

					if(canProceed(nextY,nextX)) {
						data.push(new Point(nextY,nextX));
					}
				}

		}

