				flag[j][i-1]=1;
				mapping(map,flag,i-1,j);
			}
		}
		if(j!=0){
			if(map[j-1][i]==1&&flag[j-1][i]==0){
				flag[j-1][i]=1;
				mapping(map,flag,i,j-1);
			}
