			if(map[j+1][i]==1&&flag[j+1][i]==0){
				flag[j+1][i]=1;
				mapping(map,flag,i,j+1);
			}
		}
		if(i!=0&&j!=0){
			if(map[j-1][i-1]==1&&flag[j-1][i-1]==0){
				flag[j-1][i-1]=1;
				mapping(map,flag,i-1,j-1);
			}
		}
		if(i!=0&&j!=h-1){
			if(map[j+1][i-1]==1&&flag[j+1][i-1]==0){
