class Area {
    private int[][] fld;

    Area(int[][] fld) {
        this.fld = fld;
    }

    int count() {
        int rslt = 0;
        for(int y = 0; y < fld.length; y++) {
            for(int x = 0; x < fld[y].length; x++) {
                if(fld[y][x] > 0) {
                    rslt++;
                    sink(y, x);
                }
            }
        }
        return rslt;
    }

    private void sink(int y, int x) {
        try {
            if(fld[y][x] > 0) {
                fld[y][x] = 0;
                int[][] vector = {
                    {-1, -1, -1, 0, 0, 1, 1, 1}, {-1, 0, 1, -1, 1, -1, 0, 1}
                };
                for(int i = 0; i < 8; i++) {
                    sink(y + vector[0][i], x + vector[1][i]);
                }
            }
        } catch(ArrayIndexOutOfBoundsException ignore) {}
    }
}

