	public static void addUnionFind(int a[][], int b, int c, boolean d[][])
	{
		//System.err.println("UnionFind" + " " + b%a.length + " " + b/a.length + " " + c%a.length + " " + c/a.length);
		int e = b;
		while(true)
		{
			boolean tempb = d[e%a.length][e/a.length];
			if(tempb) break;
			e = a[e%a.length][e/a.length];
		}
		//System.err.println("EDEFINED");
		int f = c;
		while(true)
		{
			boolean tempb = d[f%a.length][f/a.length];
			//System.err.println("F: " + f + " " + tempb);
			if(tempb) break;
			f = a[f%a.length][f/a.length];
		}
		//System.err.println("FDEFINED");
		//System.err.println("e:" + e + " f:" + f + " b:" + b + " c:" + c + " " + a[b%a.length][b/a.length] + " " + a[c%a.length][c/a.length]);
		d[c%a.length][c/a.length] = false;
		a[c%a.length][c/a.length] = b;
		//System.err.println("e:" + e + " f:" + f + " b:" + b + " c:" + c + " " + a[b%a.length][b/a.length] + " " + a[c%a.length][c/a.length]);
		if(e == f) return;
		else if(e > f)
		{
			d[e%a.length][e/a.length] = false;
			a[e%a.length][e/a.length] = f;
		}
		else
		{
			d[f%a.length][f/a.length] = false;
			a[f%a.length][f/a.length] = e;
		}
	}

