			w = sc.nextInt();
			h = sc.nextInt();
			if(w == 0 && h == 0){
				break;
			}
			map = new byte[h][w];
			count = 0;
			for(y = 0; y < h; y++){
				for(x = 0; x < w; x++){
					map[y][x] = sc.nextByte();
				}
			}
			for(y = 0; y < h; y++){
				for(x = 0; x < w; x++){
					count += Main.checkAround(map, x, y, w, h);
				}
			}
			System.out.println(count);
		}
	}
	public static int checkAround(byte map[][], int px, int py, int w, int h){
