			return 0;
		}
		map[py][px] = 0;
		Main.checkAround(map, px - 1, py - 1, w, h);
		Main.checkAround(map, px + 1, py + 1, w, h);
		Main.checkAround(map, px - 1, py + 1, w, h);
		Main.checkAround(map, px + 1, py - 1, w, h);
