import java.util.Scanner;

public class Main {
	private static int W,H;
	private static int[][] c;
	private static boolean[][] seen;

	private static int[] dh = {1, -1, 0, 0, 1, -1, 1, -1};
	private static int[] dw = {0, 0, 1, -1, 1, 1, -1, -1};

	private static void dfs(int[][] c, int h, int w) {
		// c(h,w)を探索済みとする
		seen[h][w] = true;
		int nextH, nextW;
		// 8方向を探索する
		for(int i = 0; i < 8; i++) {
			nextH = h + dh[i];
			nextW = w + dw[i];
			// 領域外である場合、探索しない
			if(nextH < 0 || nextW < 0 || nextH >= H || nextW >= W) {
				continue;
			}
			// 海である場合、探索しない
			if(c[nextH][nextW] == 0) {
				continue;
			}
			// 探索済みである場合、探索しない
			if(seen[nextH][nextW]) {
				continue;
			}
			dfs(c, nextH, nextW);
		}
	}

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);

		W = scan.nextInt();
		H = scan.nextInt();

		while(!(W == 0 && H == 0)) {
			c = new int[H][W];
			seen = new boolean[H][W];
			for(int i = 0; i < H; i++) {
				for(int j = 0; j < W; j++) {
					c[i][j] = scan.nextInt();

					// 全ての領域を未探索状態にする
					seen[i][j] = false;
				}
			}

			int count = 0;
			// 全ての領域を探索する
			for(int i = 0; i < H; i++) {
				for(int j = 0; j < W; j++) {
					// 探索済みであるまたは海である場合、探索は行わない
					if(!seen[i][j] && c[i][j] == 1) {
						dfs(c, i, j);
						count++;
					}
				}
			}
			System.out.println(count);
			W = scan.nextInt();
			H = scan.nextInt();
		}
		scan.close();

	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.*;

public class Main {

    static void dfs(int h, int w) {
        if (grid[h][w] == 0) return;
        grid[h][w] = 0;

        for (int i = -1; i <= 1; ++i) {
            for (int j = -1; j <= 1; ++j) {
                int nh = h + i;
                int nw = w + j;

                if (nh < 0 || nh >= H || nw < 0 || nw >= W) continue;
                if (grid[nh][nw] == 0) continue;
                dfs(nh, nw);
            }
        }
    }

    static int W, H;
    static int[][] grid;

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        while (true) {
            W = fs.nextInt();
            H = fs.nextInt();
            if (W == 0 && H == 0) break;
            grid = new int[H][W];
            for (int i = 0; i < H; ++i) {
                for (int j = 0; j < W; ++j) {
                    grid[i][j] = fs.nextInt();
                }
            }

            int cnt = 0;
            for (int i = 0; i < H; ++i) {
                for (int j = 0; j < W; ++j) {
                    if (grid[i][j] != 0) {
                        dfs(i, j);
                        ++cnt;
                    }
                }
            }

            System.out.println(cnt);
        }
    }
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }

    public double nextDouble() { return Double.parseDouble(next());}
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);

        int w = sc.nextInt();
        int h = sc.nextInt();

        while(h != 0 || w != 0) {
            int[][] island = new int[h + 2][w + 2];

            for(int i = 0; i <= h + 1; i++) {
                island[i][0] = 0;
                island[i][w + 1] = 0;
            }
            for(int i = 1; i <= w; i++){
                island[0][i] = 0;
                island[h + 1][i] = 0;
            }

            for (int i = 1; i <= h; i++) {
                for (int j = 1; j <= w; j++)
                    island[i][j] = sc.nextInt();
            }

            System.out.println(countIsland(island, h, w));

            w = sc.nextInt();
            h = sc.nextInt();
        }
        sc.close();
    }

    private static int countIsland(int[][] island, int h, int w){
        int index = 2;
        for(int i = 1; i <= h; i++){
            for(int j = 1; j <= w; j++){
                if(island[i][j] == 1){
                    island[i][j] = index++;
                    if(island[i - 1][j - 1] == 1)
                        island[i - 1][j - 1] = island[i][j];
                    if(island[i - 1][j + 1] == 1)
                        island[i - 1][j + 1] = island[i][j];
