import java.awt.Point;
import java.util.LinkedList;
import java.util.Scanner;

public class Main {

	static int W, H;
	static int[][] map;
	static int[][] check;

	static void bfs(int sx, int sy)
	{
		LinkedList<Point> queue = new LinkedList<Point>();
    	queue.offer(new Point(sx, sy));

    	while (!queue.isEmpty()) {
			Point p = queue.poll();

			if( !((0 <= p.x) && (p.x < W)) ) continue;
			if( !((0 <= p.y) && (p.y < H)) ) continue;
			if(check[p.y][p.x] == 1) continue;
			if(map[p.y][p.x] == 0) continue;

			check[p.y][p.x] = 1;

			queue.offer(new Point(p.x - 1, p.y - 1));
			queue.offer(new Point(p.x - 1, p.y));
			queue.offer(new Point(p.x - 1, p.y + 1));
			queue.offer(new Point(p.x    , p.y - 1));
			queue.offer(new Point(p.x    , p.y + 1));
			queue.offer(new Point(p.x + 1, p.y - 1));
			queue.offer(new Point(p.x + 1, p.y));
			queue.offer(new Point(p.x + 1, p.y + 1));
		}
	}

    static void start()
    {
    	check = new int[H][W];
    	for (int y = 0; y < H; y++) {
			for (int x = 0; x < W; x++) {
				check[y][x] = 0;
			}
		}

    	int count = 0;
    	for (int y = 0; y < H; y++) {
			for (int x = 0; x < W; x++) {
				if(map[y][x] == 0) continue;
				if(check[y][x] == 1) continue;
				count++;
				bfs(x, y);
			}
		}

    	System.out.println(count);
    }

    public static void main(String[] args)
    {
        Scanner sca = new Scanner(System.in);

        while(true)
        {
        	W = sca.nextInt();
        	H = sca.nextInt();
        	if(W == 0) break;

        	map = new int[H][W];
        	for (int y = 0; y < H; y++) {
				for (int x = 0; x < W; x++) {
					map[y][x] = sca.nextInt();
				}
			}

            start();
        }

    }
}

import java.util.Scanner;

public class Main {
    // 0 = sea 1= land
    static char[][] island ;
    static boolean[][] visited ;
    static int w ,h;
    public static void main(String [] args) {
        Scanner sc = new Scanner(System.in);
        w = sc.nextInt();
        h = sc.nextInt();
        island = new char[h][w];
        visited = new boolean[h][w];
        int cnt = 0;
        for (int i = 0; i < h; i++) {
            island[i] = sc.next().toCharArray();
        }
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                for (int k = 0; k < h; k++) {
                    for (int l = 0; l < w; l++) {
                        //falseに
                        visited[k][l] = false;
                    }
                }
                if (dfs(i, j) != 0){
                    cnt++;
                }
            }
        }
        System.out.println(cnt);
    }

    static int dfs(int x, int y) {
        if (x < 0 || x >= h || y < 0 || y >= w)
            return 0;
        //海であった場合
        if (island[x][y] == '0')
            return 0;
        //探索していれば
        if (visited[x][y])
            return 0;
        visited[x][y] = true;
        //隣り合ういずれかに陸地がある
        return dfs(x + 1, y) + dfs(x, y + 1) + dfs(x - 1, y) +
                dfs(x, y - 1) +dfs(x+1,y-1)+dfs(x-1,y+1) +
                dfs(x + 1, y+1)+ dfs(x - 1, y-1) +1;
    }
}

import java.util.*;
import java.lang.*;

/**
 * HowManyIslands
 */
public class Main {

    public static void main(String[] args) {
        int tate[] = { -1, -1, -1, 0 };
        int yoko[] = { -1, 0, 1, -1 };

        Scanner sc = new Scanner(System.in);
        while (true) {
            int w = sc.nextInt();
            int h = sc.nextInt();

            int list[][] = new int[h][w];

            if (w == 0 && h == 0)
                return;

            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    list[i][j] = sc.nextInt();
                }
            }

            // ここでUnionFind
            int parent[] = new int[w * h]; // 親の番号(親なら全体の大きさをマイナスで)格納
            for (int i = 0; i < w * h; i++) {
                if (list[i / w][i % w] == 0) {
                    parent[i] = 0;
                } else {
                    parent[i] = -1;
                }
            }

            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    // 1マスずつ見る
                    if (list[i][j] == 1) {
                        for (int k = 0; k < 4; k++) {
                            try {
                                if (list[i + tate[k]][j + yoko[k]] == 1) {
                                    connect(i * w + j, (i + tate[k]) * w + j + yoko[k], parent);
                                }
                            } catch (Exception e) {

                            }
                        }
                    }
                }
            }

            int ans = 0;
            for (int i = 0; i < w * h; i++) {
                if (parent[i] < 0) {
                    ans++;
                }
            }

            System.out.println(ans);

        }

    }

    // 親の番号を返す
    private static int root(int n, int[] parent) {
        if (parent[n] < 0) {
            return n;
        } else {
            return root(parent[n], parent);
        }
    }

    private static int size(int n, int[] parent) {
        return -parent[root(n, parent)];
    }

    private static boolean connect(int a, int b, int[] parent) {
        a = root(a, parent);
        b = root(b, parent);

        if (a == b) // 元々同じ仲間なら
            return false;

        if (size(a, parent) < size(b, parent)) {
            int tmp = a;
            a = b;
            b = tmp;
        }

        parent[a] += parent[b];
        parent[b] = a;

        return true;
    }
}

import java.util.ArrayDeque;
import java.util.Scanner;

public class Main {
    static final int[] dx = {0, 1, 0, -1, 1, -1, -1, 1}, dy = {1, 0, -1, 0, 1, 1, -1, -1};
    static int w, h;
    static int[][] board;

    static class Pair {
        int x, y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static void walk(int x, int y) {
        ArrayDeque<Pair> que = new ArrayDeque<>();

        que.push(new Pair(x, y));
        while (!que.isEmpty()) {
            Pair p = que.poll();
            board[p.y][p.x] = 0;
            for (int i = 0; i < 8; ++i) {
                int nx = p.x + dx[i], ny = p.y + dy[i];
                if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;

                if (board[ny][nx] == 1) {
                    que.push(new Pair(nx, ny));
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        while (true) {
            w = scanner.nextInt();
            h = scanner.nextInt();

            if (w == 0 && h == 0) break;

            board = new int[h][w];
            int ans = 0;

            for (int i = 0; i < h; ++i) {
                for (int j = 0; j < w; ++j) {
                    board[i][j] = scanner.nextInt();
                }
            }

            for (int i = 0; i < h; ++i) {
                for (int j = 0; j < w; ++j) {
                    if (board[i][j] == 1) {
                        ++ans;
                        walk(j, i);
                    }
                }
            }

            System.out.println(ans);
        }
    }
}

