class Main{

    // 深さ優先探索
    void dfs(HashMap<Integer, List<Integer>> graph, int v, boolean[] seen){
        seen[v] = true;
        if(!graph.containsKey(v) || graph.get(v).size() == 0) return;

        List<Integer> todo = graph.get(v);
        for(int next : todo){
            if(seen[next]) continue;
            dfs(graph, next, seen);
        }
    }

    void solve(){
        int W = ni();
        int H = ni();
        List<Integer> ans = new ArrayList<>();

        while(W != 0 && H != 0){
            HashMap<Integer, List<Integer>> graph = new HashMap<>();
            List<Integer> list;
            boolean[] seen = new boolean[5051];
            int[][] field = new int[H + 2][W + 2];
            for(int i = 1; i <= H; i++){
                for(int j = 1; j <= W; j++){
                    field[i][j] = ni();
                }
            }
            for(int i = 1; i <= H; i++){
                for(int j = 1; j <= W; j++){
                    if(field[i][j] == 0) continue;
                    int pre = i * 100 + j;
                    list = new ArrayList<>();
                    for(int y = i - 1; y <= i + 1; y++){
                        for(int x = j - 1; x <= j + 1; x++){
                            if(x == j && y == i) continue;
                            if(field[y][x] == 1) list.add(y * 100 + x);
                        }
                    }
                    graph.put(pre, list);
                }
            }

            int count = 0;
            for(int v : graph.keySet()){
                if(seen[v]) continue;
                dfs(graph, v, seen);
                count++;
            }
            ans.add(count);

            W = ni();
            H = ni();
        }

        ans.forEach(System.out::println);
    }

    public static void main(String[] args){
        new Main().solve();
    }

