//深さ優先探索を用いる
public class Main{
  public static int[] dx = {1, 1, 1, 0, -1, -1, -1, 0};
  public static int[] dy = {1, 0, -1, -1, -1, 0, 1, 1};


  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    while(true){
      int w = Integer.parseInt(sc.next());
      int h = Integer.parseInt(sc.next());
      if(h == 0 && w == 0){
        break;
      }
      int[][] c = new int[h][w];//島の情報(海か陸か)
      int [][] seen = new int[h][w];//探索済みか？初期値0
      //初期化用
      for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
          c[i][j] = Integer.parseInt(sc.next());
          seen[i][j] = 0;
        }
      }

      //探索用
      int k = 1;//島の数(k-1)
      for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
          //falseが返ってきたとき初手で島が見つからなかったからkは増やさない
          if(dfs(true, k, c, seen, j, i, h, w)) k++;
        }
      }
      System.out.printf("%d\n", k - 1);

      /*for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
          System.out.printf("%d", [i][j]);
        }
        System.out.printf("\n");
      }*/
    }
  }

  //深さ優先探索(引数が多くて気持ち悪い) グローバル変数を用いるしかないのか？
  public static boolean dfs(boolean flag, int num, int[][] c, int[][] seen, int x, int y, int h, int w){
    //初手が探索済みの陸もしくは海ならばfalseを返す
    if(flag && (seen[y][x] != 0 || c[y][x] == 0)){
      return false;
    }
    //初手以外で領域外、海、探索済みだった場合trueを返す
    else if( x >= w || y >= h || x < 0 || y < 0 || c[y][x] == 0 || seen[y][x] != 0){
      return true;
    }
    else{
      //陸ならば同一のナンバーで管理する
      seen[y][x] = num;
      for(int _x: dx){
        for(int _y:dy){
          //上下左右斜めで再起で探索
          dfs(false, num, c, seen, x + _x, y + _y, h, w);
        }
      }
      //true
      return true;
    }
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

public class Main {
    private final int[][] search = new int[][]{
            {0, 1},
            {0, -1},
            {1, 1},
            {1, -1},
            {1, 0},
            {-1, 1},
            {-1, 0},
            {-1, -1}
    };

    public static void main(final String[] args) throws IOException {
        new Main().run();
    }

    private void run() throws IOException {
        boolean b = true;
        final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        while (b) {
            b = runOnce(reader);
        }

        reader.close();
    }

    private boolean runOnce(final BufferedReader reader) throws IOException {
        final String[] params = reader.readLine().split(" ");
        final int x = Integer.parseInt(params[0]);
        final int y = Integer.parseInt(params[1]);
        if (x == 0 && y == 0) return false;

        final Map<Field, Boolean> fields = new HashMap<>();
        for (int i = 0; i < y; i++) {
            final String[] line = reader.readLine().split(" ");
            for (int j = 0; j < line.length; j++) {
                fields.put(new Field(i, j, line[j].equals("1")), line[j].equals("1"));
            }
        }
        int landCount = 0;
        while (true) {
            final Iterator<Field> iterator = fields.keySet().iterator();
            if (!iterator.hasNext()) {
                break;
            }
            final Field next = iterator.next();
            if (next.land) {
                searchLand(next, fields);
                landCount++;
            } else {
                fields.remove(next);
            }
        }
        System.out.println(landCount);
        return true;
    }

    private void searchLand(final Field field, final Map<Field, Boolean> fields) {
        fields.remove(field);

        final Field tmp = new Field(0, 0, true);
        for (final int[] s: search) {
            tmp.x = field.x + s[0];
            tmp.y = field.y + s[1];
            if(fields.containsKey(tmp)) {
                if (fields.get(tmp)) {
                    searchLand(tmp, fields);
                }
                fields.remove(tmp);
            }
        }
    }

    private final class Field {
        int x, y;
        boolean land;

        Field(final int x, final int y, final boolean land) {
            this.x = x;
            this.y = y;
            this.land = land;
        }

        @Override
        public int hashCode() {
            return x * 2 + y * 101 + (land ? 1 : 0);
        }

        @Override
        public boolean equals(final Object obj) {
            if (obj instanceof Field) {
                return ((Field) obj).x == this.x && ((Field) obj).y == this.y;
            }
            return super.equals(obj);
        }
    }
}

