        int w = sc.nextInt();
        int h = sc.nextInt();

        while(h != 0 || w != 0) {
            int[][] island = new int[h + 2][w + 2];

            for(int i = 0; i <= h + 1; i++) {
                island[i][0] = 0;
                island[i][w + 1] = 0;
            }
            for(int i = 1; i <= w; i++){
                island[0][i] = 0;
                island[h + 1][i] = 0;
            }

            for (int i = 1; i <= h; i++) {
                for (int j = 1; j <= w; j++)
                    island[i][j] = sc.nextInt();
            }

            System.out.println(countIsland(island, h, w));

            w = sc.nextInt();
            h = sc.nextInt();
        }
        sc.close();
    }

    private static int countIsland(int[][] island, int h, int w){

        int index = 2;
        for(int i = 1; i <= h; i++){
            for(int j = 1; j <= w; j++){
                if(island[i][j] == 1){
                    island[i][j] = index++;
                    if(island[i - 1][j - 1] == 1)
                        island[i - 1][j - 1] = island[i][j];
                    if(island[i - 1][j + 1] == 1)
                        island[i - 1][j + 1] = island[i][j];
                    if(island[i + 1][j - 1] == 1)
                        island[i + 1][j - 1] = island[i][j];
                    if(island[i + 1][j + 1] != 0)
                        island[i + 1][j + 1] = island[i][j];
                }
            }
        }

        int flag = 0;
        while(flag == 0){
            flag = 1;
            for(int i = 1; i <= h; i++){
                for(int j = 1; j <= w; j++){
                    if(island[i][j] != 0){
                        if(island[i][j] < island[i - 1][j - 1]) {
                            flag = 0;
                            island[i - 1][j - 1] = island[i][j];
                        }
                        if(island[i][j] > island[i - 1][j - 1]) {
                            flag = 0;
                            island[i][j] = island[i - 1][j - 1];
                        }
                        if(island[i][j] < island[i - 1][j + 1]) {
                            flag = 0;
                            island[i - 1][j + 1] = island[i][j];
                        }
                        if(island[i][j] > island[i - 1][j + 1]) {
                            flag = 0;
                            island[i][j] = island[i - 1][j + 1];
                        }
                        if(island[i][j] < island[i + 1][j - 1]) {
                            flag = 0;
                            island[i + 1][j - 1] = island[i][j];
                        }
                        if(island[i][j] > island[i + 1][j - 1]) {
                            flag = 0;
                            island[i][j] = island[i + 1][j - 1];
                        }
                        if(island[i][j] < island[i + 1][j + 1]) {
                            flag = 0;
                            island[i + 1][j + 1] = island[i][j];
                        }
                        if(island[i][j] > island[i + 1][j + 1]) {
                            flag = 0;
                            island[i][j] = island[i + 1][j + 1];
                        }
                    }
                }
            }
        }

        for(int i = 1; i <= h; i++){
            for(int j = 1; j <= w; j++){
                if(island[i][j] != 0){
                    for(int k = 1; k <= h; k++){
                        for(int l = 1; l <= w; l++){
                            if(island[k][l] == island[i][j] && (k != i || l != j))
                                island[k][l] = 0;
                        }
                    }
                }
            }
        }

        int count = 0;

        for(int i = 1; i <= h; i++){
            for(int j = 1; j <= w; j++){
                if(island[i][j] != 0)
                    count++;
            }
        }

        return count;
    }
}

import java.util.Scanner;

public class Main {
	public static void main(String args[]) {
		Scanner scr = new Scanner(System.in);
		while (true) {
			String[] ss = scr.nextLine().split(" ", 0);
			stage_size = new int[2];
			stage_size[0] = Integer.parseInt(ss[0]);
			stage_size[1] = Integer.parseInt(ss[1]);
			if (stage_size[0] == 0)
				break;
			stage = new int[stage_size[0]][stage_size[1]];
			visited = new boolean[stage_size[0]][stage_size[1]];
			for (int y = 0; y < stage_size[1]; y++) {
				String[] data = scr.nextLine().split(" ", 0);
				for (int x = 0; x < data.length; x++) {
					stage[x][y] = Integer.parseInt(data[x]);
					visited[x][y] = false;
				}
			}
			System.out.println(Islands());
		}
		scr.close();
	}

	static int[] stage_size;
	static int[][] stage;
	static boolean[][] visited;

	private static int Islands() {
		int islands = 0;
		for (int x = 0; x < stage.length; x++) {
			for (int y = 0; y < stage[x].length; y++) {
				if (visited[x][y] || stage[x][y] == 0)
					continue;
				else {
					Visit(x, y);
					islands++;
				}
			}
		}
		return islands;
	}

	private static void Visit(int x, int y) {
		if (x >= stage.length || y >= stage[0].length || x < 0 || y < 0 || stage[x][y] == 0)
			return;
		if (stage[x][y] == 1) {
			visited[x][y] = true;
			Visit(x + 1, y);
			Visit(x, y + 1);
			Visit(x + 1, y + 1);
			Visit(x + 1, y - 1);
			VisitUp(x, y - 1);
		}
	}

	private static void VisitUp(int x, int y) {
		if (x >= stage.length || y >= stage[0].length || x < 0 || y < 0 || stage[x][y] == 0)
			return;
		if (stage[x][y] == 1 || !visited[x][y+1]) {
			visited[x][y] = true;
			VisitUp(x, y - 1);
		}
	}

}

