  private static final int[] dy = { 0, 1, 1, 1, 0, -1, -1, -1 };

  private static void dfs(int i, int j, boolean[][] isLand, int H, int W) {
    isLand[i][j] = false;
    for (int k = 0; k < 8; k++) {
      int ci = i + dx[k];
      int cj = j + dy[k];
      if (0 <= ci && ci < H && 0 <= cj && cj < W && isLand[ci][cj]) {
        dfs(ci, cj, isLand, H, W);
      }
    }
  }

