    Point(int a, int b) {
      this.x = a;
      this.y = b;
    }
  }

  static int W, H;
  static int map[][];
  static ArrayDeque<Point> stack;
  static int x8[] = {0, 1, 1, 1, 0, -1, -1, -1};
  static int y8[] = {1, 1, 0, -1, -1, -1, 0, 1};

  static void bfs() {
    while (!stack.isEmpty()) {
      Point p = stack.removeFirst();
      for (int i = 0; i < 8; i++) {
        int nx = p.x + x8[i];
        int ny = p.y + y8[i];
        if (nx < W && ny < H && nx >= 0 && ny >= 0) {
          if (map[ny][nx] == 1) {
            stack.addLast(new Point(nx, ny));
            map[ny][nx]++;
          }
        }
      }
    }
  }

