public class Main {
	public static void main(String args[]) {
		Scanner scr = new Scanner(System.in);
		while (true) {
			String[] ss = scr.nextLine().split(" ", 0);
			stage_size = new int[2];
			stage_size[0] = Integer.parseInt(ss[0]);
			stage_size[1] = Integer.parseInt(ss[1]);
			if (stage_size[0] == 0)
				break;
			stage = new int[stage_size[0]][stage_size[1]];
			visited = new boolean[stage_size[0]][stage_size[1]];
			for (int y = 0; y < stage_size[1]; y++) {
				String[] data = scr.nextLine().split(" ", 0);
				for (int x = 0; x < data.length; x++) {
					stage[x][y] = Integer.parseInt(data[x]);
					visited[x][y] = false;
				}
			}
			System.out.println(Islands());
		}
		scr.close();
	}

	static int[] stage_size;
	static int[][] stage;
	static boolean[][] visited;

	private static int Islands() {
		int islands = 0;
		for (int x = 0; x < stage.length; x++) {
			for (int y = 0; y < stage[x].length; y++) {
				if (visited[x][y] || stage[x][y] == 0)
					continue;
				else {
					Visit(x, y);
					islands++;
				}
			}
		}
		return islands;
	}

	private static void Visit(int x, int y) {
		if (x >= stage.length || y >= stage[0].length || x < 0 || y < 0)
			return;
		if (stage[x][y] == 1) {
			visited[x][y] = true;
			Visit(x + 1, y);
			Visit(x, y + 1);
			Visit(x + 1, y + 1);
			Visit(x + 1, y - 1);
		}
	}

}

import java.io.*;
import java.util.*;

class Field{
	final char SEA ='0';
	final char LAND='1';

	StringBuilder map;
	int width;
	int height;

	Field(int w,int h, String[][] buf){
		width = w;
		height= h;
		map= new StringBuilder();
		StringBuilder edge= new StringBuilder();
		for(int i=0;i<w+2;i++){
			edge.append(SEA);
		}
		map.append(edge);
		for(int i=0;i<h;i++){
			map.append(SEA);
			for(int j=0;j<w;j++){
				map.append(buf[i][j]);
			}
			map.append(SEA);
		}
		map.append(edge);
	}

	int point2int(int x, int y){
		return (width+2)*y + x;
	}
	int int2x(int n){
		return n%(width+2);
	}
	int int2y(int n){
		return n/(width+2);
	}

	int[] neighbor(int x, int y){
		int[] neib= {point2int(x-1,y-1),point2int(x,y-1),point2int(x+1,y-1),
				     point2int(x-1,y  ),                 point2int(x+1,y  ),
				     point2int(x-1,y+1),point2int(x,y+1),point2int(x+1,y+1)};
		return neib;
	}
	int[] neighbor(int n){
		int x= int2x(n); int y= int2y(n);
		int[] neib= {point2int(x-1,y-1),point2int(x,y-1),point2int(x+1,y-1),
			         point2int(x-1,y  ),                 point2int(x+1,y  ),
			         point2int(x-1,y+1),point2int(x,y+1),point2int(x+1,y+1)};
		return neib;
	}

	char charAt(int x, int y){
		return map.charAt(point2int(x,y));
	}
	char charAt(int n){
		int x= int2x(n); int y= int2y(n);
		return map.charAt(point2int(x,y));
	}

	void traverse(){
		Deque<Integer> dfs= new LinkedList<Integer>();
		int tmp;
		int cnt=0;
		while ( ( tmp=map.indexOf(String.valueOf(LAND)) ) >=0 ) {
			cnt++;
			dfs.push(tmp);
			map.setCharAt(tmp, SEA);
			while (!dfs.isEmpty()) {
				tmp = dfs.peek();
				boolean reached = true;
				for(int i=0; i<neighbor(tmp).length; i++) {
					int next = neighbor(tmp)[i];
					if ( charAt(next) == LAND ) {
						dfs.push(next);
						map.setCharAt(next, SEA);
						reached = false;
					}
				}
				if (reached) {
					dfs.pop();
				}
			} 
		}
		System.out.println(cnt);
	}
}

