		}

		int count = 0;
		for (int y = 0; y < h; y++) {
			for (int x = 0; x < w; x++) {
				if(island[y][x] == 1){
					count++;
					dfs(y, x, h, w);
				}
			}
		}
		System.out.println(count);
		}
	}

	public static int[] vi={-1,1,0,0,-1,-1,1,1}, vj={0,0,-1,1,-1,1,-1,1};
	public static void dfs(int i, int j, int r, int c){
		for(int k = 0; k < 8; k++){
			int ni = i+vi[k], nj = j+vj[k];
			if(inside(ni, nj, r, c) && island[ni][nj] == 1){
				island[ni][nj] = 0;
				dfs(ni,nj,r,c);
			}
		}
	}
}

