class A1160 {

	int[] xdis = { -1, 0, +1, 0 ,-1,-1,1,1};
	int[] ydis = { 0, -1, 0, +1 ,-1,1,-1,1};

	int[][] cm;

	public void ans(Scanner sc) {
		while (true) {
			int W = sc.nextInt();
			int H = sc.nextInt();

			if (W == 0) {
				break;
			}

			cm = new int[H][W];

			for (int h = 0; h < H; h++) {
				for (int w = 0; w < W; w++) {
					cm[h][w] = sc.nextInt();
				}
			}

			int count = 0;
			for (int h = 0; h < H; h++) {
				for (int w = 0; w < W; w++) {
					if (cm[h][w] == 1) {
						count++;
						rec(w, h);
					}
				}
			}

			System.out.println(count);

		}
	}

	void rec(int x, int y) {
		if (y < 0 || cm.length <= y) {
			return;
		}
		if (x < 0 || cm[0].length <= x) {
			return;
		}
		if (cm[y][x] != 1) {
			return;
		}

		cm[y][x] = -1;
		for (int i = 0; i < xdis.length; i++) {
			rec(x + xdis[i], y + ydis[i]);
		}
	}
}

