class A1166 {
	LinkedList<Node> list;

	public void ans(Scanner sc) {
		while (true) {
			int W = sc.nextInt();
			int H = sc.nextInt();

			if (W == 0) {
				break;
			}

			list = new LinkedList<A1166.Node>();
			for (int i = 0; i < W * H; i++) {
				list.add(new Node());
			}

			for (int h = 0; h < (H * 2 - 1); h++) {
				int hh = (h / 2) * W;
				if (h % 2 == 0) {
					for (int w = 0; w < W - 1; w++) {
						int x = sc.nextInt();
						if (x == 0) {
							list.get(hh + w).addTo(hh + w + 1);
							list.get(hh + w + 1).addTo(hh + w);
						}
					}
				} else {
					for (int w = 0; w < W; w++) {
						int x = sc.nextInt();
						if (x == 0) {
							list.get(hh + w).addTo(hh + w + W);
							list.get(hh + w + W).addTo(hh + w);
						}
					}

				}
			}

			rec(0, 1);

			int ans = list.getLast().getTmp();

			if (ans == Integer.MAX_VALUE) {
				System.out.println(0);
			} else {
				System.out.println(list.getLast().getTmp());
			}
		}
	}

	void rec(int c, int cost) {
		Node n = list.get(c);

		if (cost < n.getTmp()) {
			n.setTmp(cost);
			LinkedList<Integer> li = n.getToList();
			for (Iterator iterator = li.iterator(); iterator.hasNext();) {
				Integer integer = (Integer) iterator.next();
				rec(integer, cost + 1);
			}
		}

	}

	class Node {
		LinkedList<Integer> toList;
		int tmp;

		Node() {
			toList = new LinkedList<Integer>();
			tmp = Integer.MAX_VALUE;
		}

		void addTo(int to) {
			toList.add(to);
		}

		public LinkedList<Integer> getToList() {
			return toList;
		}

		public void setTmp(int tmp) {
			this.tmp = tmp;
		}

		public int getTmp() {
			return tmp;
		}
	}

}

class A1180 {

	public void ans(Scanner sc) {
		while (true) {
			int A = sc.nextInt();
			int L = sc.nextInt();

			if (A == 0 && L == 0) {
				break;
			}

			LinkedList<Integer> list = new LinkedList<Integer>();
			list.add(A);

			while (true) {
				int a = list.getLast();
				int ind = list.indexOf(a);
				if (ind != list.size() - 1) {
					System.out.printf("%d %d %d\n", ind, a, ((list.size() - 1) - ind));
					break;
				}

				int[] nums = new int[10];
				int l = L - (int) Math.log10(a) - 1;
				if (a == 0) {
					l = L;
				}
				nums[0] += l;
				for (int i = 0; i < L - l; i++) {
					nums[a % 10]++;
					a /= 10;
				}

				StringBuilder min = new StringBuilder("");
				for (int i = 0; i < 10; i++) {
					for (int j = 0; j < nums[i]; j++) {
						min.append(i);
					}
				}

				String max = min.reverse().toString();
				min.reverse();

				int ans = Integer.parseInt(max) - Integer.parseInt(min.toString());

				list.add(ans);

			}
		}
	}
}

