namespace aoj1160 {
	class Program {
		static void Main (string[] args) {
			while (true) {
				int w, h;
				var whstr = Console.ReadLine();
				var wh = whstr.Split(' ');
				w = int.Parse(wh[0]);
				h = int.Parse(wh[1]);
				if (w == 0)
					break;
				int[,] shima = new int[w, h];
				int i, j, numShima = 0;
				for (j = 0;j < h;j++) {
					var wstr = Console.ReadLine().Split(' ');
					for (i = 0;i < w;i++) {
						shima[i, j] = int.Parse(wstr[i]);
					}
				}
				for (i = 0;i < w;i++) {
					for (j = 0;j < h;j++) {
						if (judge(shima, i, j, w, h))
							numShima++;
					}
				}
				Console.WriteLine(numShima);
			}
		}

		static bool judge (int[,] map, int x, int y, int w, int h) {
			if (map[x, y] == 0)
				return false;
			map[x, y] = 0;
			if (0 < x)
				judge(map, x - 1, y, w, h);
			if (x + 1 < w)
				judge(map, x + 1, y, w, h);
			if (0 < y)
				judge(map, x, y - 1, w, h);
			if (y + 1 < h)
				judge(map, x, y + 1, w, h);

			return true;
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace CSharpSample01
{

    struct Point
    {
        public int h;
        public int w;
    }


    class Program
    {




        static void DFS(int H, int W, int[,] map, bool[,] visit, int sh, int sw)
        {
            Stack<Point> st = new Stack<Point>();
            st.Push(new Point() { h = sh, w = sw });
            visit[sh, sw] = true;
            bool flag = false;
            Point now;

            while(st.Count != 0)
            {
                flag = false;
                now = st.Peek();
                int nh = now.h;
                int nw = now.w;

                //上
                if(nh - 1 >= 0 && map[nh - 1, nw] == 1 && !visit[nh - 1, nw])
                {
                    visit[nh - 1, nw] = true;
                    st.Push(new Point() { h = nh - 1, w = nw });
                    flag = true;
                }
                //右上
                else if(nh - 1 >= 0 && nw + 1 < W && map[nh - 1, nw + 1] == 1 && !visit[nh - 1, nw + 1])
                {
                    visit[nh - 1, nw + 1] = true;
                    st.Push(new Point() { h = nh - 1, w = nw + 1 });
                    flag = true;
                }              
                //右
                else if(nw + 1 < W && map[nh, nw + 1] == 1 && !visit[nh, nw + 1])
                {
                    visit[nh, nw + 1] = true;
                    st.Push(new Point() { h = nh, w = nw + 1 });
                    flag = true;
                }
                //右下
                else if (nh + 1 < H && nw + 1 < W && map[nh + 1, nw + 1] == 1 && !visit[nh + 1, nw + 1])
                {
                    visit[nh + 1, nw + 1] = true;
                    st.Push(new Point() { h = nh + 1, w = nw + 1 });
                    flag = true;
                }
                //下
                else if (nh + 1 < H && map[nh + 1, nw] == 1 && !visit[nh + 1, nw])
                {
                    visit[nh + 1, nw] = true;
                    st.Push(new Point() { h = nh + 1, w = nw });
                    flag = true;
                }
                //左下
                else if (nh + 1 < H && nw - 1 >= 0 && map[nh + 1, nw - 1] == 1 && !visit[nh + 1, nw - 1])
                {
                    visit[nh + 1, nw - 1] = true;
                    st.Push(new Point() { h = nh + 1, w = nw - 1 });
                    flag = true;
                }
                //左
                else if (nw - 1 >= 0 && map[nh, nw - 1] == 1 && !visit[nh, nw - 1])
                {
                    visit[nh, nw - 1] = true;
                    st.Push(new Point() { h = nh, w = nw - 1 });
                    flag = true;
                }
                //左上
                else if (nh - 1 >= 0 && nw - 1 >= 0 && map[nh - 1, nw - 1] == 1 && !visit[nh - 1, nw - 1])
                {
                    visit[nh - 1, nw - 1] = true;
                    st.Push(new Point() { h = nh - 1, w = nw - 1 });
                    flag = true;
                }


                if (!flag)
                {
                    st.Pop();
                }

            }

        }

        static int Solve(int H, int W, int[,] map)
        {
            bool[,] visit = new bool[H, W];
            int cnt_island = 0;

            //visit初期化
            for(int i = 0; i < H; i++)
            {
                for(int j = 0; j < W; j++)
                {
                    visit[i, j] = false;
                }
            }

            for(int i = 0; i < H; i++)
            {
                for(int j = 0; j < W; j++)
                {
                    if(map[i, j] == 1 && !visit[i, j])
                    {
                        DFS(H, W, map, visit, i, j);
                        cnt_island++;
                    }
                }
            }



            return cnt_island;
        }



        static void Main(string[] args)
        {
            while (true)
            {                
                string[] input = Console.ReadLine().Split(' ');
                int W = int.Parse(input[0]);
                int H = int.Parse(input[1]);

                if (W == 0 && H == 0) break;

                int[,] map = new int[H, W];

                for(int i = 0; i < H; i++)
                {
                    string[] str = Console.ReadLine().Split(' ');
                    for(int j = 0; j < W; j++)
                    {
                        if (str[j] == "1") map[i, j] = 1;
                        else map[i, j] = 0;
                    }
                }


                Console.WriteLine(Solve(H, W, map));
            }

        }
    }
}

