    static void DFS(Vector2Int current,  string[][] nodes, HashSet<Vector2Int> yet)
    {

        yet.Remove(current);
        foreach (var dir in Vector2Int.AllDirections8)
        {
            Vector2Int newPos = current + dir;

            if (newPos.X >= 0 && newPos.X < nodes[0].Length && newPos.Y >= 0 && newPos.Y < nodes.Length)
            {
                if (nodes[current.Y][current.X] == "0") continue;
                if (yet.Contains(newPos)) DFS(newPos, nodes, yet);
            }
        }


    }

    static Vector2Int BinarySearch(IEnumerable<int> numbers, Func<int, bool> judge)
    {
        int max = numbers.Count();
        int min = -1;
        int mid = (min + max) / 2;

        while (max - min > 1)
        {
            if (judge(numbers.ElementAt(mid)))
            {
                min = mid;
                mid = (mid + max) / 2;
            }
            else
            {
                max = mid;
                mid = (mid + min) / 2;
            }
        }

        if (max == numbers.Count()) return new Vector2Int(mid, mid + 1);
        else if (min == -1) return new Vector2Int(-1, 0);
        else
        {
            return judge(numbers.ElementAt(mid)) != judge(numbers.ElementAt(mid + 1)) ? new Vector2Int(mid, mid + 1)
            : new Vector2Int(mid - 1, mid);
        }
    }


