public class Program
{

    public void Proc()
    {
        int[] inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
        while(inpt.Sum()>0) {
            Console.WriteLine(GetAns(inpt[1], inpt[0]));
            inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
        }
    }

    private int GetAns(int h, int w) {
        bool[,] map = new bool[h, w];
        for (int i = 0; i < h; i++) {
            bool[] inpt = Reader.ReadLine().Split(' ').Select(a => a[0] != '0').ToArray();
            for (int j = 0; j < w; j++) {
                map[i, j] = inpt[j];
            }
        }
        int ans = 0;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if(map[i,j]) {
                    CountIsl(i, j, map);
                    ans++;
                }
            }
        }
        return ans;
    }

    private void CountIsl(int h, int w, bool[,] map)
    {
        map[h, w] = false;

        for (int i = Math.Max(0, h - 1); i <= Math.Min(map.GetLength(0) - 1, h + 1); i++) {
            for (int j = Math.Max(0, w - 1); j <= Math.Min(map.GetLength(1) - 1, w + 1);j++) {
                if(!map[i, j]) {
                    continue;
                }
                CountIsl(i, j, map);
            }
        }
    }

