class UnionFind
{
    private int[] 親; //親[i] : iの親の番号

    public UnionFind(int N) //コンストラクタ、すべてが根として初期化
    {
        親 = new int[N];
        for (int i = 0; i < N; i++)
            親[i] = i;
    }

    public int Root(int x) //xの属する木の根を返す
    {
        if (親[x] == x) return x;
        return 親[x] = Root(親[x]);
    }

    public void Unite(int x, int y) //xとyの木を統合
    {
        int rx = Root(x);
        int ry = Root(y);
        if (rx == ry) return;
        親[rx] = ry;
    }

    public bool Same(int x, int y) //xとyが同じ木に属するかどうかを返す
    {
        return Root(x) == Root(y);
    }
}

