    class Program
    {
        static Func<string, int> par = s => int.Parse(s);
        static Queue<int> Q = new Queue<int>();
        static int w,h;
        static bool[,] Atlas;
        static string[] ss;
        static List<int> A = new List<int>(),G=new List<int>();
        static Action<int> RS= (i) =>  ss = Console.ReadLine().Split(' ');
        static void Main(string[] args)
        {
            RS(0);
            w = par(ss[0]);h = par(ss[1]);
            Atlas = new bool[h,w];
            for (int i = 0; i < h; i++)
            {
                RS(0);
                for (int j = 0; j < w; j++)
                {
                    switch (par(ss[j])) {
                        case 0: Atlas[i, j] = false;break;
                        case 1: Atlas[i, j] = true; A.Add(i*w+j); break;
                    }
                }
            }
            bool b=true;int R = 0;
            while (A.Count > 0)
            {
                while (b)
                {
                    b = false; Q.Enqueue(A.First()); A.RemoveAt(0);
                    foreach (int a in A)
                    {
                        if (Adja(a))
                        {
                            Q.Enqueue(a); G.Add(a); if (!b) b = true;
                        }
                    }
                }
                foreach (int g in G) A.Remove(g);
                R++;
                Q.Clear(); G.Clear();
            }
            Console.WriteLine(R);
            Console.ReadLine();
        }
        static int[] K=new int[9];
        static bool Adja(int j) {
            for (int i = 0; i < 3; i++) for(int k=0;k<3;k++)K[i*3+k]=j+(i-1)*w+k-1;
            foreach (int l in K) if (Q.Contains(l)) return true;
            return false;
        }
    }

