        {
            var answer = new List<int>();

            while (true)
            {
                var firstLine = Console.ReadLine().Split(' ').Select(value => int.Parse(value)).ToArray();
                var w = firstLine[0];
                var h = firstLine[1];

                if(w == 0 && h == 0)
                {
                    break;
                }

                var map = new List<char[]>();
                var isArrived = new bool[h, w];

                for (var i = 0; i < h; i++)
                {
                    map.Add(Console.ReadLine().Split(' ').Select(value => char.Parse(value)).ToArray());

                    for (var j = 0; j < w; j++)
                    {
                        if (map[i][j] == '0')
                        {
                            isArrived[i, j] = true;
                        }
                    }
                }

                var count = 0;
                for (var i = 0; i < h; i++)
                {
                    for (var j = 0; j < w; j++)
                    {
                        if (!isArrived[i, j])
                        {
                            count++;
                            Dfs(i, j, map, isArrived);
                        }
                    }
                }

                answer.Add(count);
            }

            answer.ForEach(value => Console.WriteLine($"{value}"));
        }

        private static void Dfs(int i, int j, List<char[]> map, bool[,] isArrived)
        {
            isArrived[i, j] = true;

            for(var y = i - 1; y <= i + 1; y++)
            {
                for(var x = j - 1; x <= j + 1; x++)
                {
                    if(y < 0 || map.Count <= y || x < 0 || map[0].Length <= x)
                    {
                        continue;
                    }

                    if(!isArrived[y, x] && map[y][x] == '1')
                    {
                        Dfs(y, x, map, isArrived);
                    }
                }
            }
        }
    }
}

