namespace Competitive
{
    internal class Solution
    {
        public int H, W;
        public int[,] M;
        public int[] DX = new int[] { 1, 0, -1, 0, 1, 1, -1, -1 };
        public int[] DY = new int[] { 0, 1, 0, -1, 1, -1, 1, -1};
        public int ret;

        public void Run()
        {
            while (true)
            {
                {
                    var line = Input.ReadIntArray();
                    W = line[0];
                    H = line[1];
                }
                if (W == 0 && H == 0) return;

                M = new int[H, W];
                for (int y = 0; y < H; y++)
                {
                    var line = Input.ReadIntArray();
                    for (int x = 0; x < W; x++)
                        M[y, x] = line[x];
                }

                DFSRun();
                Console.WriteLine(ret);
            }
        }

        public void DFSRun()
        {
            ret = 0;
            for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++)
            {
                if (M[y, x] == 1)
                {
                    DFS(y, x);
                    ret++;
                }
            }
        }

        public void DFS(int y, int x)
        {
            if (M[y, x] == 0) return;
            M[y, x] = 0;
            for (int i = 0; i < DY.Length; i++)
            {
                int yy = y + DY[i];
                int xx = x + DX[i];
                if (0 <= yy && yy < H && 0 <= xx && xx < W)
                    DFS(yy, xx);
            }
        }

    }

