        {
            while (true)
            {
                int w, h;
                int answer = 0;
                string[] s = Console.ReadLine().Split();
                w = int.Parse(s[0]); h = int.Parse(s[1]);
                if (w == 0 && h == 0) break;
                int[,] table = new int[h, w];
                for(int i = 0; i < h; i++)
                {
                    string[] num = Console.ReadLine().Split();
                    for(int j = 0; j < w; j++)
                    {
                        table[i, j] = int.Parse(num[j]);
                    }
                }
                for(int i = 0; i < h; i++)
                {
                    for(int j = 0; j < w; j++)
                    {
                        answer += checker(table,i,j);
                    }
                }
                Console.WriteLine(answer);
            }
        }

        static int checker(int[,] table, int x, int y)
        {
            if (table[x, y] == 0) return 0;

            if (x < 0 || y < 0 || y >= table.GetLength(0) || x >= table.GetLength(1)) return 0;

            checker(table, x + 1, y);
            checker(table, x - 1, y);
            checker(table, x + 1, y - 1);
            checker(table, x , y - 1);
            checker(table, x - 1, y - 1);
            checker(table, x + 1, y + 1);
            checker(table, x , y + 1);
            checker(table, x - 1, y + 1);

            return 1;
        }
    }
}

