                            count++;
                        }
                    }
                }
                Console.WriteLine(count);
            }
        }

        static bool[,] DFS(bool[,] map, int y, int x)
        {
            var stk = new Stack();
            stk.Push(new int[] { y, x });
            while (stk.Count > 0)
            {
                var yx = (int[])stk.Pop();
                for (int i = 0; i < wds.Length; i++)
                {
                    int dy = hds[i];
                    int dx = wds[i];
                    if (map[yx[0] + dy, yx[1] + dx])
                    {
