function culc(_input) {
  var args = _input;
  var W = args[0].split(' ')[0];
  var H = args[0].split(' ')[1];
  var graph = new Array(H);
  var seen = new Array(H);

  for (var i = 0; i < H; i++) {
    graph[i] = new Array(W);
    seen[i] = new Array(W);
    var line = args[i + 1].split(' ');

    for (var j = 0; j < W; j++) {
      graph[i][j] = line[j];
      seen[i][j] = false;
    }
  }

  var count = 0;

  for (var _i = 0; _i < H; _i++) {
    for (var _j = 0; _j < W; _j++) {
      if (seen[_i][_j]) continue;
      if (graph[_i][_j] == 0) continue;
      count++;
      dfs(graph, seen, _j, _i);
    }
  }

  console.log(count);
}

