function dfs(graph, seen, startx, starty) {
  seen[starty][startx] = true;

  for (var i = 0; i < 8; i++) {
    var nextx = startx + dx[i];
    var nexty = starty + dy[i];
    if (nextx >= graph[0].length || nextx < 0) continue;
    if (nexty >= graph.length || nexty < 0) continue;
    if (graph[nexty][nextx] == 0) continue;
    if (seen[nexty][nextx]) continue;
    dfs(graph, seen, nextx, nexty);
  }
}

