func DFS(field [][]int, h, w int) {
	field[h][w] = 0
	for dh := -1; dh <= 1; dh++ {
		for dw := -1; dw <= 1; dw++ {
			ch, cw := h+dh, w+dw
			if ch < 0 || len(field) <= ch || cw < 0 || len(field[0]) <= cw || field[ch][cw] == 0 {
				continue
			}
			DFS(field, ch, cw)
		}
	}
}

func Solve(field [][]int) int {
	count := 0
	for h, row := range field {
		for w, c := range row {
			if c == 0 {
				continue
			}
			DFS(field, h, w)
			count++
		}
	}
	return count
}

