// Sieve

type Sieve struct {
	n          int
	primes     []int
	maxFactors []int
}

func NewSieve(n int) *Sieve {
	sieve := &Sieve{
		n:          n,
		primes:     []int{},
		maxFactors: make([]int, n+1, n+1),
	}
	sieve.init()
	return sieve
}

func (s *Sieve) init() {
	s.maxFactors[0] = -1
	s.maxFactors[1] = -1
	for i := 2; i <= s.n; i++ {
		if s.maxFactors[i] != 0 {
			continue
		}
		s.primes = append(s.primes, i)
		s.maxFactors[i] = i
		for j := i * i; j <= s.n; j += i {
			if s.maxFactors[j] == 0 {
				s.maxFactors[j] = i
			}
		}
	}
}

func (s *Sieve) IsPrime(x int) bool {
	return s.maxFactors[x] == x
}

func (s *Sieve) PrimeFactorization(x int) map[int]int {
	m := map[int]int{}
	for x != 1 {
		m[s.maxFactors[x]]++
		x /= s.maxFactors[x]
	}
	return m
}

