        auto ans = solve(h, w, g);

        writeln(ans);
    }
}


int solve(int h, int w, int[][] g) {
    auto v = new bool[][](h, w);

    int ans;

    int[] di = [1, -1, 0, 0, 1, 1, -1, -1];
    int[] dj = [0, 0, 1, -1, 1, -1, 1, -1];

    void dfs(int i, int j) {
        v[i][j] = true;

        foreach (k ; 0 .. 8) {
            int ni = i + di[k];
            int nj = j + dj[k];
            if (ni < 0 || nj < 0 || ni >= h || nj >= w) continue;
            if (v[ni][nj] || !g[ni][nj]) continue;
            dfs(ni, nj);
        }
    }

    foreach (i ; 0 .. h) {
        foreach (j ; 0 .. w) {
            if (g[i][j] && !v[i][j]) {
                dfs(i, j);
                ans++;
            }

            debug {
                writefln("%(%s\n%)", v);
            }
        }
    }

    return ans;
}







