class RecursiveDepthFirstSearch(object):

    def __init__(self, width, height, stage):
        self.width = width
        self.height = height
        self.stage = stage

    def search(self, x0, y0):
        if x0 < 0 or self.width <= x0 or y0 < 0 or self.height <= y0:
            pass
        elif self.stage[x0][y0] == 0:
            pass
        else:
            self.stage[x0][y0] = 0
            for dx, dy in itertools.product(range(-1, 2), range(-1, 2)):
                if dx != 0 or dy != 0:
                    self.search(x0 + dx, y0 + dy)


