class IslandMap:
    moves = list(itertools.product([-1, 0, 1], [-1, 0, 1]))

    def __init__(self, w, h, c):
        self.w = w
        self.h = h
        self.c = c

    def dfs(self, p):
        self.c[p[0]][p[1]] = 0
        for m in IslandMap.moves:
            n = (p[0] + m[0], p[1] + m[1])
            if 0 <= n[0] < self.h and 0 <= n[1] < self.w:
                if self.c[n[0]][n[1]] == 1:
                    self.dfs(n)

    def solve(self):
