use std::str::FromStr;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char) 
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let mut ans: Vec<usize> = Vec::new();
    loop {
        let w: usize = read();
        let h: usize = read();
        if w == 0 || h == 0 {
            break;
        }
        let map: Vec<Vec<u8>> = (0..h).map(|_| (0..w).map(|_| read()).collect()).collect();
        let mut seen: Vec<Vec<bool>> = (0..h).map(|_| (0..w).map(|_| false).collect()).collect();
        let mut sum = 0;
        for hi in 0..h {
            for wi in 0..w {
                if dfs(&map, &mut seen, wi, hi, w, h) {
                    sum += 1;
                }
            }
        }
        ans.push(sum);
    }
    for i in ans {
        println!("{}", i);
    }
}

fn dfs(map: &Vec<Vec<u8>>, seen: &mut Vec<Vec<bool>>, x: usize, y: usize, w: usize, h: usize) -> bool {
    if seen[y][x] || map[y][x] == 0 {
        seen[y][x] = true;
        return false;
    }
    seen[y][x] = true;
    if x > 0 && y > 0 {
        dfs(map, seen, x-1, y-1, w, h);
    }
    if x > 0 {
        dfs(map, seen, x-1, y, w, h);
    }
    if y > 0 {
        dfs(map, seen, x, y-1, w, h);
    }
    if x < w-1 && y < h-1 {
        dfs(map, seen, x+1, y+1, w, h);
    } 
    if x < w-1 {
        dfs(map, seen, x+1, y, w, h);
    }
    if y < h-1 {
        dfs(map, seen, x, y+1, w, h);
    }
    if x > 0 && y < h-1 {
        dfs(map, seen, x-1, y+1, w, h);
    }
    if x < w-1 && y > 0 {
        dfs(map, seen, x+1, y-1, w, h);
    }
    return true;
}

