fn dfs((i, j, done, w, h, isLand): (usize, usize, &mut Vec<Vec<bool>>, usize,usize, &Vec<Vec<bool>>)) {
    done[i][j] = true;
    for ni in (max(i, 1)-1)..i+1+1 {
        for nj in (max(j, 1)-1)..j+1+1 {
            if ni == i && nj == j {continue;}

            let i = (); let j = ();
            if ni >= h || nj >= w { continue; }
            if done[ni][nj] { continue; }
            if isLand[ni][nj] { dfs((ni,nj,done,w,h,isLand)) }
        }
    }
}


fn solve((w,h,map,): (usize,usize,Vec<Vec<u32>>,)) -> u32 {
    let isLand: Vec<Vec<bool>> = map.iter().map(|x| x.iter().map(|&y| y==1).collect()).collect();
    let mut done = vec![vec![false; w];h];
    let mut ans = 0;
    for i in 0..h {
        for j in 0..w {
            if !done[i][j] && isLand[i][j] {
                ans += 1;
                dfs((i,j,&mut done, w,h,& isLand));

            }
        }
    }
    ans
}


