struct UnionFind {
    size: usize,
    pos: Vec<isize>,
}
impl UnionFind {
    fn new(n: usize) -> Self {
        let size = n;
        let pos = vec![-1; n + 1];
        UnionFind { size, pos }
    }
    fn find(&mut self, x: usize) -> usize {
        if self.pos[x] < 0 {
            x
        } else {
            let v = self.pos[x] as usize;
            self.pos[x] = self.find(v) as isize;
            self.pos[x] as usize
        }
    }
    fn unite(&mut self, x: usize, y: usize) -> Result<(), ()> {
        let mut x = self.find(x);
        let mut y = self.find(y);
        if x == y {
            return Err(());
        };
        if self.pos[x] > self.pos[y] {
            std::mem::swap(&mut x, &mut y);
        }
        self.pos[x] += self.pos[y];
        self.pos[y] = x as isize;
        Ok(())
    }
    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
    fn size(&mut self, x: usize) -> usize {
        let x = self.find(x);
        -self.pos[x] as usize
    }
}


fn main(){
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin);
    loop {
        let W: usize = sc.read();
        let H: usize = sc.read();
        if W == 0 { break; };
        let mut g = vec![vec![0i32; W]; H];
        for i in 0..H {
            for j in 0..W {
                g[i][j] = sc.read();
            }
        }
        let mut uf = UnionFind::new(H*W);
        for i in 0..H {
            for j in 0..W {
                if g[i][j] == 0 { continue; };
                if j < W - 1 && g[i][j+1] > 0 {
                    uf.unite(i*W + j, i*W + j + 1).ok();
                }
                if i + 1 < H && g[i+1][j] > 0 {
                    uf.unite(i*W + j, i*W + j + W).ok();
                }
                if i + 1 < H && j + 1 < W && g[i+1][j+1] > 0 {
                    uf.unite(i*W + j, i*W + j + 1 + W).ok();
                }
                if i > 0 && j + 1 < W && g[i-1][j+1] > 0 {
                    uf.unite(i*W + j, i*W + j + 1 - W).ok();
                }
            }
        }
        let mut cnt = 0;
        for i in 0..H {
            for j in 0..W {
                if g[i][j] > 0 && uf.find(i*W + j) == i*W + j {
                    cnt += 1;
                }
            }
        }
        println!("{}", cnt);
    }
}

