fn dfs(map: &Vec<Vec<usize>>, used: &mut Vec<Vec<bool>>, current: (i64, i64), w: usize, h: usize) {
    let x = vec![1, 1, 1, 0, 0, -1, -1, -1];
    let y = vec![1, 0, -1, 1, -1, 1, 0, -1];

    if used[current.1 as usize][current.0 as usize] {
        return;
    }
    used[current.1 as usize][current.0 as usize] = true;

    for i in 0..8 {
        let (nx, ny) = (current.0 + x[i], current.1 + y[i]);
        if nx >= 0
            && ny >= 0
            && nx < w as i64
            && ny < h as i64
            && map[ny as usize][nx as usize] == 1
        {
            dfs(map, used, (nx, ny), w, h);
        }
    }
}

